-- ============================================================
-- 003 — Drill seed, part 02 of 07  (40 drills)
--
-- Paste into the Supabase SQL editor and run. Parts are independent and
-- idempotent: re-running one updates those rows rather than duplicating them.
--
-- Requires scripts/002_drill_content.sql to have been applied first.
-- ============================================================

INSERT INTO public.drills (
  slug, name, category, subcategory, type, level, duration_min, player_count, group_size, description, objective, setup, instructions, coaching_cues, common_errors, variations, tags, diagram_type, diagram_data
) VALUES
  ('FT-006', 'Resistance Band Lateral Walk: Hip Strength Foundation', 'Fitness', 'Strength', 'fitness', 'beginner', 12, 1, 'individual', 'Strengthen the hip abductors and glutes through resistance band lateral walks — the muscle groups most directly responsible for explosive lateral movement in tennis. Weak hips are the most common physical cause of slow court coverage and lower extremity injuries. This drill builds the hip strength foundation that makes all other footwork training more effective.', 'Strengthen the hip abductors and glutes through resistance band lateral walks — the muscle groups most directly responsible for explosive lateral movement in tennis. Weak hips are the most common physical cause of slow court coverage and lower extremity injuries. This drill builds the hip strength foundation that makes all other footwork training more effective.', 'Player 1 wears a resistance band around the ankles or just above the knees. The band should provide noticeable resistance during lateral movement but not prevent it. Player 1 walks laterally across the baseline in a partial squat position.', ARRAY['Place the resistance band around both ankles (lighter) or above both knees (heavier).','Assume a partial squat: knees bent to 30 degrees, hips pushed back, torso upright.','Walk laterally 10 steps to the right — keeping constant tension on the band.','Walk laterally 10 steps back to the left.','Complete 3 sets of 10 steps in each direction. Rest 30 seconds between sets.']::text[], ARRAY['Maintain the squat depth throughout — don''t stand up to make the steps easier.','Keep the feet parallel — don''t let the toes turn out as the hip flexors fatigue.','Push off the stepping foot first — don''t drag the trailing foot.','Keep tension on the band at all times — the trailing foot should never fully close to the lead foot.','Feel the burn on the outside of the hip and glute — that is the target muscle.']::text[], ARRAY['Standing up during the walk — removes the hip loading.','Dragging the trailing foot until it touches the lead foot — releases band tension.','Toes turning outward — indicates hip abductor fatigue, reduce resistance.']::text[], ARRAY['Band lateral shuffle: perform the shuffle at faster pace rather than walking.','Band squat walk forward: walk diagonally forward — simulates approach footwork with resistance.','Band spider run: perform the spider run pattern with the band — extreme hip challenge.']::text[], ARRAY['fitness','resistance band','hip strength','beginner','injury prevention','lateral']::text[], 'json', '{"p1":{"x":200,"y":850},"moves":[{"x1":200,"y1":850,"x2":310,"y2":850},{"x1":310,"y1":850,"x2":200,"y2":850},{"x1":200,"y1":850,"x2":90,"y2":850}],"areas":[{"x":200,"y":850,"r":20}]}'::jsonb),
  ('FT-007', 'Plank Series: Core Stability for Tennis', 'Fitness', 'Strength', 'fitness', 'beginner', 12, 1, 'individual', 'Build core stability through a plank series specifically designed for the demands of tennis. The core is the transfer point for all rotational power in tennis strokes — a weak core wastes the power generated by the legs and arms. The plank series trains the ability to maintain core rigidity under sustained load, which translates directly into more consistent, powerful groundstrokes across a full match.', 'Build core stability through a plank series specifically designed for the demands of tennis. The core is the transfer point for all rotational power in tennis strokes — a weak core wastes the power generated by the legs and arms. The plank series trains the ability to maintain core rigidity under sustained load, which translates directly into more consistent, powerful groundstrokes across a full match.', 'Player 1 needs only a mat or flat surface. No equipment needed. The series covers: standard plank, side plank, plank with rotation, and plank with shoulder taps.', ARRAY['Standard plank: forearms on the ground, body straight — hold 45 seconds.','Right side plank: right forearm on the ground, body straight — hold 30 seconds.','Left side plank: left forearm on the ground, body straight — hold 30 seconds.','Plank with rotation: from high plank, rotate the body to one side and back — 10 reps each side.','Plank with shoulder taps: from high plank, tap each shoulder alternately — 20 taps total.','Rest 60 seconds between exercises. Complete the full series 2 times.']::text[], ARRAY['Body must be completely straight — no sagging hips or piked hips.','Engage the glutes as well as the core — the glutes prevent hip sagging.','Breathe throughout — many players hold their breath during planks.','On the rotation plank, rotate from the shoulder, not the hip — targets the obliques.','On shoulder taps, resist the rotation with the core — the hips should not sway.']::text[], ARRAY['Sagging hips — reduces core activation and strains the lower back.','Raised hips — easier but doesn''t train the correct muscles.','Holding breath — causes blood pressure spikes and reduces duration.']::text[], ARRAY['Plank hold progression: track maximum plank hold time weekly.','Dynamic plank: move from forearm plank to high plank and back — 15 reps.','Tennis ball tap: in high plank, tap a tennis ball forward and back with each hand — coordination challenge.']::text[], ARRAY['fitness','plank','core','beginner','stability','strength']::text[], 'json', '{"p1":{"x":200,"y":850},"areas":[{"x":200,"y":850,"r":30}]}'::jsonb),
  ('FT-008', 'Box Jump Circuit: Explosive Leg Power', 'Fitness', 'Explosive Power', 'fitness', 'intermediate', 15, 1, 'individual', 'Build explosive leg power through box jumps — the most effective single exercise for developing the power needed for explosive first steps, split steps, and overhead jumps in tennis. Box jumps train the stretch-shortening cycle: loading the legs rapidly and releasing that energy explosively. Players with strong box jump scores consistently move better on court.', 'Build explosive leg power through box jumps — the most effective single exercise for developing the power needed for explosive first steps, split steps, and overhead jumps in tennis. Box jumps train the stretch-shortening cycle: loading the legs rapidly and releasing that energy explosively. Players with strong box jump scores consistently move better on court.', 'Player 1 uses a sturdy box, bench, or step 12-18 inches high. The surface must be non-slip. Alternatively, mark a height on a wall and jump to touch it. Safety note: start with lower heights until the landing is controlled.', ARRAY['Stand in front of the box, feet hip-width apart.','Lower into a quarter squat and immediately jump onto the box — land softly on both feet.','Step down carefully — don''t jump down.','Complete 8 box jumps per set. Rest 60 seconds. Play 4 sets.','Focus on the speed of the jump, not the height — power is about how fast you can load and explode.']::text[], ARRAY['Load quickly — the squat dip should be fast, not a slow descent.','Drive the arms upward simultaneously with the leg push — they add 20% more power.','Land softly: absorb through the ankles, knees, and hips in sequence.','Full hip extension at the top — don''t jump with bent hips.','Reset completely between jumps — this is a power drill, not an endurance drill.']::text[], ARRAY['Slow squat dip — a slow load produces a weak jump. Dip must be fast.','Hard landings — indicates poor absorption, increases injury risk.','Jumping down from the box — step down to protect the knees.']::text[], ARRAY['Lateral box jump: jump sideways onto the box — builds lateral explosive power.','Single-leg box jump: one-leg takeoff — extreme power and balance challenge.','Box jump to broad jump: land on the box, jump forward off the box onto the ground.']::text[], ARRAY['fitness','box jump','explosive power','intermediate','legs','plyometric']::text[], 'json', '{"p1":{"x":200,"y":850},"moves":[{"x1":200,"y1":850,"x2":200,"y2":820},{"x1":200,"y1":820,"x2":200,"y2":850}],"areas":[{"x":200,"y":835,"r":20}]}'::jsonb),
  ('FT-009', 'Shoulder Stability Circuit: Injury Prevention for Servers', 'Fitness', 'Injury Prevention', 'fitness', 'beginner', 15, 1, 'individual', 'Strengthen the rotator cuff and shoulder stabilizers — the muscles most commonly injured in tennis players. The serve and overhead smash place enormous stress on the shoulder joint. Weak rotator cuff muscles cannot adequately decelerate the arm after contact, leading to tendinitis, tears, and chronic pain. This circuit provides the minimum shoulder maintenance work every tennis player should do.', 'Strengthen the rotator cuff and shoulder stabilizers — the muscles most commonly injured in tennis players. The serve and overhead smash place enormous stress on the shoulder joint. Weak rotator cuff muscles cannot adequately decelerate the arm after contact, leading to tendinitis, tears, and chronic pain. This circuit provides the minimum shoulder maintenance work every tennis player should do.', 'Player 1 needs a light resistance band (yellow or green) or 1-2kg dumbbells. The exercises are performed standing or seated. These are low-weight, high-rep exercises — the goal is muscle endurance, not strength.', ARRAY['External rotation: band around a post, elbow at 90 degrees, rotate the forearm outward — 3 x 15 reps.','Internal rotation: same setup, rotate inward — 3 x 15 reps.','Prone Y: lie face down, arms extended in Y shape, lift arms — 3 x 12 reps.','Prone T: same position, arms extended in T shape, lift arms — 3 x 12 reps.','Sleeper stretch: lying on the shoulder, gently press the forearm down — hold 30 seconds each side.','Complete the full circuit 2 times. Rest 30 seconds between exercises.']::text[], ARRAY['Light weight is correct — these exercises target tiny stabilizers, not big muscles.','Slow and controlled motion on every rep — ballistic movements defeat the purpose.','Feel the back of the shoulder working — if you feel it in the front, the weight is too heavy.','The sleeper stretch addresses internal rotation tightness — very common in dominant shoulders.','This circuit should be done 3 times per week, not just before matches.']::text[], ARRAY['Using too much weight — the stabilizers cannot handle heavy loads.','Fast, momentum-driven reps — removes the stabilizer activation.','Only doing this when injured — prevention is far more effective than rehabilitation.']::text[], ARRAY['Theraband rainbow: arm overhead, loop band around hand, trace a rainbow arc — advanced stabilizer.','Wall slide: forearms on wall, slide arms up and down — scapular stability training.','Side-lying external rotation: same motion lying on the side — pure isolator position.']::text[], ARRAY['fitness','shoulder','injury prevention','beginner','rotator cuff','stability']::text[], 'json', '{"p1":{"x":200,"y":850},"areas":[{"x":200,"y":850,"r":25}]}'::jsonb),
  ('FT-010', 'High-Intensity Baseline Rally Fitness: 30-30 Protocol', 'Fitness', 'Aerobic Conditioning', 'fitness', 'intermediate', 20, 2, 'pairs', 'Build tennis-specific aerobic fitness through a structured high-intensity rally protocol. The 30-30 protocol — 30 seconds of maximum-intensity rallying followed by 30 seconds of rest — directly trains the cardiovascular system at the exact intensities required for competitive match play. Unlike isolated sprints, this drill combines the fitness demand with actual ball-striking.', 'Build tennis-specific aerobic fitness through a structured high-intensity rally protocol. The 30-30 protocol — 30 seconds of maximum-intensity rallying followed by 30 seconds of rest — directly trains the cardiovascular system at the exact intensities required for competitive match play. Unlike isolated sprints, this drill combines the fitness demand with actual ball-striking.', 'Both players at the baseline. A timer signals start and stop. Both players rally at maximum sustainable pace for 30 seconds, then rest for 30 seconds. The rally must be kept alive — if the ball is missed, both players restart immediately.', ARRAY['Both players rally at maximum pace for 30 seconds — every shot hit hard and deep.','Timer signals rest — both players stop immediately, breathe, and recover.','30 seconds rest — use it fully: breathe, relax the grip, walk.','Timer signals restart — immediate return to maximum pace.','Complete 10 rounds of 30-30. Total active time: 5 minutes. Total rest: 5 minutes.']::text[], ARRAY['Maximum pace means genuine maximum — not medium pace. This is a fitness drill.','Keep the rally alive at all costs — a dead rally means less fitness training time.','Use the rest period actively: walk, breathe deeply, shake out the arms.','If the pace drops in the last 3 rounds, fitness is the limiting factor.','This protocol should feel harder each round — that''s the point.']::text[], ARRAY['Medium pace during the work interval — not developing match-specific fitness.','Continuing to rally during rest — the rest is as important as the work.','Stopping when the ball is missed instead of restarting immediately.']::text[], ARRAY['40-20 protocol: 40 seconds work, 20 seconds rest — more demanding.','20-10 Tabata protocol: 20 seconds max, 10 seconds rest — extreme intensity.','One directional: both players rally cross-court forehand only — adds a placement constraint.']::text[], ARRAY['fitness','30-30','aerobic','intermediate','rally','match-simulation']::text[], 'json', '{"p1":{"x":280,"y":850},"p2":{"x":120,"y":60},"shots":[{"x1":280,"y1":840,"x2":110,"y2":90},{"x1":120,"y1":70,"x2":275,"y2":835}],"areas":[{"x":110,"y":100,"r":35},{"x":275,"y":820,"r":35}]}'::jsonb),
  ('FT-011', 'Single-Leg Romanian Deadlift: Hamstring and Balance', 'Fitness', 'Strength', 'fitness', 'intermediate', 12, 1, 'individual', 'Strengthen the hamstrings, glutes, and single-leg balance through the single-leg Romanian deadlift — one of the most valuable exercises for tennis players. The single-leg RDL mimics the single-leg loading that occurs on every wide ball retrieval, approach shot, and split step. Weak hamstrings are directly linked to hamstring strains — the most common muscle injury in tennis.', 'Strengthen the hamstrings, glutes, and single-leg balance through the single-leg Romanian deadlift — one of the most valuable exercises for tennis players. The single-leg RDL mimics the single-leg loading that occurs on every wide ball retrieval, approach shot, and split step. Weak hamstrings are directly linked to hamstring strains — the most common muscle injury in tennis.', 'Player 1 uses a dumbbell (5-10kg) or a tennis ball can for light resistance. One leg is the working leg; the other leg extends behind. Start with body weight if new to the movement.', ARRAY['Stand on the right leg, slight bend in the knee.','Hinge forward at the hip, extending the left leg behind for balance.','Lower until the torso is parallel to the ground (or as far as hamstring flexibility allows).','Drive through the right heel to return to standing.','Complete 10 reps per leg per set. Rest 45 seconds. Play 3 sets.']::text[], ARRAY['Hinge at the hip — the back stays straight throughout, not rounded.','Feel the stretch in the standing leg''s hamstring — that''s the target muscle.','Keep the extended leg in line with the torso — like a seesaw.','Drive through the heel to stand — not through the toes.','Slow descent (3 seconds), controlled — not a fast drop.']::text[], ARRAY['Rounding the back — compresses the spine, removes hamstring activation.','Bending the standing knee too much — turns it into a squat, not a hip hinge.','Not going low enough — reduces hamstring range of motion training.']::text[], ARRAY['Two-leg RDL: beginner version with both feet on the ground.','Weighted single-leg RDL: add a dumbbell for progressive resistance.','Reach and return: at the bottom of the RDL, reach the hand toward the opposite foot.']::text[], ARRAY['fitness','Romanian deadlift','hamstring','intermediate','strength','balance']::text[], 'json', '{"p1":{"x":200,"y":850},"areas":[{"x":200,"y":850,"r":25}]}'::jsonb),
  ('FT-012', 'Agility Ladder Advanced: Tennis-Specific Patterns', 'Fitness', 'Agility', 'fitness', 'intermediate', 12, 1, 'individual', 'Build foot speed and movement pattern variety through advanced agility ladder sequences specifically chosen for tennis movements. Standard ladder drills are modified here to replicate tennis footwork: the icky shuffle simulates the baseline lateral, the in-out pattern simulates the split step, and the lateral run pattern simulates the crossover recovery. This is targeted agility training, not generic conditioning.', 'Build foot speed and movement pattern variety through advanced agility ladder sequences specifically chosen for tennis movements. Standard ladder drills are modified here to replicate tennis footwork: the icky shuffle simulates the baseline lateral, the in-out pattern simulates the split step, and the lateral run pattern simulates the crossover recovery. This is targeted agility training, not generic conditioning.', 'Player 1 uses a 6-10 rung agility ladder on the court surface. Each pattern is performed 3 times before moving to the next. Rest 20 seconds between patterns.', ARRAY['Icky shuffle: two in, one out pattern laterally through the ladder — 3 passes.','In-out: both feet in each space, then out to the side and back in — 3 passes.','Lateral single-leg: one foot in each space, moving laterally — 3 passes each direction.','T-shape run: sprint to the top of the ladder, shuffle right, shuffle left, backpedal to start.','Rest 30 seconds between patterns. Complete all 4 patterns twice.']::text[], ARRAY['Arms drive every pattern — quiet arms produce slow feet.','Eyes forward at all times — not at the ladder rungs.','Accuracy before speed — hit every rung correctly before increasing speed.','The icky shuffle should feel like a baseline shuffle — same hip height, same foot width.','The T-shape run replicates the server''s recovery footwork — practice it with serve footwork in mind.']::text[], ARRAY['Looking at the ladder — eyes must be up in all real footwork situations.','Rushing before accuracy is established — sloppy patterns don''t transfer to court movement.','Arms staying still — arms are not optional in agility work.']::text[], ARRAY['Racket carry: perform all patterns while holding the racket — adds weight and specificity.','Reaction ladder: coach calls which pattern after Player 1 is already moving.','Ladder to sprint: complete a ladder pattern then immediately sprint to a cone 10 feet away.']::text[], ARRAY['fitness','agility ladder','foot speed','intermediate','pattern','movement']::text[], 'json', '{"p1":{"x":200,"y":850},"moves":[{"x1":200,"y1":850,"x2":200,"y2":740}],"cones":[{"x":200,"y":850},{"x":200,"y":830},{"x":200,"y":810},{"x":200,"y":790},{"x":200,"y":770},{"x":200,"y":750}]}'::jsonb),
  ('FT-013', 'Wall Sit with Ball Toss: Leg Endurance Under Load', 'Fitness', 'Strength', 'fitness', 'intermediate', 10, 2, 'pairs', 'Build leg endurance and the ability to maintain technical quality under muscular fatigue through the wall sit with ball toss combination. The wall sit creates sustained quad and hip fatigue while the ball toss forces the upper body to continue functioning normally — exactly what happens in long baseline rallies where the legs tire but shots must remain consistent.', 'Build leg endurance and the ability to maintain technical quality under muscular fatigue through the wall sit with ball toss combination. The wall sit creates sustained quad and hip fatigue while the ball toss forces the upper body to continue functioning normally — exactly what happens in long baseline rallies where the legs tire but shots must remain consistent.', 'Player 1 performs a wall sit (back against a wall, thighs parallel to the floor). Player 2 tosses balls to Player 1 who must catch and toss them back while holding the wall sit position.', ARRAY['Player 1 assumes a wall sit against a wall: back flat against the wall, thighs parallel to the floor.','Player 2 tosses balls to Player 1 from 6 feet away — varying height and side.','Player 1 catches and returns each ball while maintaining the wall sit.','Continue for 45 seconds. Rest 30 seconds. Repeat 4 rounds.','Increase to 60 seconds in subsequent sessions as strength improves.']::text[], ARRAY['Thighs must be parallel to the floor — higher is easier and defeats the purpose.','Back flat against the wall — no sliding down.','Don''t hold the breath — breathe steadily throughout the hold.','Arm movement for the ball toss should be natural — don''t tighten the legs to stabilize the arms.','This simulates the third-set leg fatigue while demanding continued arm function.']::text[], ARRAY['Thighs above parallel — reduces the quad loading.','Leaning forward — back must stay against the wall.','Dropping the position to catch difficult tosses — the legs must not move.']::text[], ARRAY['Wall sit with racket swings: Player 1 shadow swings a racket while holding the wall sit.','Timed challenge: maximum wall sit time without ball — personal record tracking.','Single-leg wall sit: extremely advanced — one leg extended, one in the wall sit position.']::text[], ARRAY['fitness','wall sit','leg endurance','intermediate','fatigue','strength']::text[], 'json', '{"p1":{"x":200,"y":850},"p2":{"x":200,"y":740},"shots":[{"x1":200,"y1":750,"x2":200,"y2":840},{"x1":200,"y1":840,"x2":200,"y2":750}],"areas":[{"x":200,"y":845,"r":20}]}'::jsonb),
  ('FT-014', 'Reaction Ball Drills: Unpredictable Bounce Training', 'Fitness', 'Reactive Fitness', 'fitness', 'intermediate', 10, 1, 'individual', 'Build reactive speed and hand-eye coordination through reaction ball training. A reaction ball is an irregular-shaped rubber ball that bounces in unpredictable directions — exactly replicating the unpredictable nature of court bounces. Training with a reaction ball builds the reactive footwork speed that cannot be trained with a regular ball, and it forces the fast-twitch nervous system to operate at maximum speed.', 'Build reactive speed and hand-eye coordination through reaction ball training. A reaction ball is an irregular-shaped rubber ball that bounces in unpredictable directions — exactly replicating the unpredictable nature of court bounces. Training with a reaction ball builds the reactive footwork speed that cannot be trained with a regular ball, and it forces the fast-twitch nervous system to operate at maximum speed.', 'Player 1 uses a reaction ball (available at sports stores). Stand 3-4 feet from a wall. Throw the reaction ball against the wall and react to wherever it bounces. No racket needed — catch with hands.', ARRAY['Stand 3 feet from a wall.','Throw the reaction ball against the wall at medium force.','React to wherever it bounces — catch it before the second bounce.','Immediately rethrow against the wall and repeat.','Continue for 30 seconds. Rest 20 seconds. Complete 8 rounds.']::text[], ARRAY['Stay on the balls of the feet throughout — the reaction ball requires constant readiness.','Eyes on the ball from the moment it leaves the wall — the direction changes in the first foot of flight.','Move your feet to the ball — don''t reach with the arms.','Soft hands on the catch — absorb the velocity.','React, don''t anticipate — the reaction ball defeats anticipation deliberately.']::text[], ARRAY['Reaching with the arms instead of moving the feet — builds bad reactive habits.','Anticipating the direction — the reaction ball punishes this immediately with a miss.','Slow to react — must have weight on the balls of the feet to react quickly enough.']::text[], ARRAY['Two-wall: bounce between two walls at a corner — more unpredictable.','One-hand catch: alternate hands — tests each hand independently.','Racket reaction: use a racket to redirect the reaction ball — most tennis-specific version.']::text[], ARRAY['fitness','reaction ball','reactive','intermediate','hand-eye','speed']::text[], 'json', '{"p1":{"x":200,"y":750},"shots":[{"x1":200,"y1":740,"x2":200,"y2":480},{"x1":200,"y1":470,"x2":220,"y2":730}],"areas":[{"x":200,"y":480,"r":20}]}'::jsonb),
  ('FT-015', 'Split Squat Jump: Explosive Change of Direction', 'Fitness', 'Explosive Power', 'fitness', 'advanced', 12, 1, 'individual', 'Build explosive change-of-direction power through split squat jumps — plyometric exercises that train the body to rapidly reverse direction from a loaded position. The split squat jump replicates the physical demand of the split step followed by an explosive first step: absorb force from one direction, immediately produce force in the opposite direction. This is the exact motor pattern of match-level court movement.', 'Build explosive change-of-direction power through split squat jumps — plyometric exercises that train the body to rapidly reverse direction from a loaded position. The split squat jump replicates the physical demand of the split step followed by an explosive first step: absorb force from one direction, immediately produce force in the opposite direction. This is the exact motor pattern of match-level court movement.', 'Player 1 in a split stance (one foot forward, one back). No equipment needed. This is a bodyweight plyometric exercise. Safety: requires good single-leg strength before attempting — complete the single-leg RDL drill first.', ARRAY['Assume a split stance: right foot forward, left foot back, both knees bent to 90 degrees.','Drive off both feet and jump as high as possible.','While in the air, switch the feet — left foot lands forward, right foot lands back.','Absorb the landing softly and immediately jump again.','Complete 6 jumps per set (3 switches each leg). Rest 60 seconds. Play 4 sets.']::text[], ARRAY['Drive off both feet simultaneously — equal push from front and back.','Switch legs while in the air — the change happens at maximum height.','Soft landing — land as quietly as possible to maximize absorption.','Arms drive the jump — pump them upward aggressively.','Don''t let the knee collapse inward on landing — it must track over the foot.']::text[], ARRAY['Insufficient jump height — not enough power production.','Knee caving inward on landing — dangerous, indicates glute weakness.','Not switching legs completely — landing without a true stance change.']::text[], ARRAY['No jump: static split squat — beginner version without the plyometric component.','Weighted vest: add 5-10% of body weight — increases power demands.','Continuous protocol: 10 consecutive split squat jumps without rest — tests endurance power.']::text[], ARRAY['fitness','split squat jump','explosive','advanced','plyometric','power']::text[], 'json', '{"p1":{"x":200,"y":850},"moves":[{"x1":200,"y1":850,"x2":200,"y2":810},{"x1":200,"y1":810,"x2":200,"y2":850}],"areas":[{"x":200,"y":850,"r":25}]}'::jsonb),
  ('FT-016', 'Wrist and Forearm Circuit: Racket Control Strength', 'Fitness', 'Injury Prevention', 'fitness', 'beginner', 10, 1, 'individual', 'Strengthen the wrist flexors, extensors, and forearm muscles that control the racket face and prevent tennis elbow. Tennis elbow (lateral epicondylitis) is the most common tennis injury and is directly linked to weak forearm extensors and eccentric loading on the backhand. This circuit prevents tennis elbow and simultaneously improves racket head control and spin generation.', 'Strengthen the wrist flexors, extensors, and forearm muscles that control the racket face and prevent tennis elbow. Tennis elbow (lateral epicondylitis) is the most common tennis injury and is directly linked to weak forearm extensors and eccentric loading on the backhand. This circuit prevents tennis elbow and simultaneously improves racket head control and spin generation.', 'Player 1 uses a light dumbbell (0.5-1.5kg) or a heavy racket. The circuit is performed seated or standing. 4 exercises target all the relevant muscle groups.', ARRAY['Wrist curl: forearm on thigh, palm up, curl the weight up and down — 3 x 15 reps.','Wrist extension: forearm on thigh, palm down, lift the weight and lower — 3 x 15 reps.','Radial deviation: thumb points up, move the weight up (thumb side) and down — 3 x 12 reps.','Ulnar deviation: same position, move the weight down (pinky side) and up — 3 x 12 reps.','Finger extensions: band around fingers, open and close against resistance — 3 x 20 reps.']::text[], ARRAY['Very light weight — these are small muscles. Even 0.5kg can be challenging.','Slow and controlled — ballistic wrist movements are dangerous.','Wrist extension is the most important for tennis elbow prevention — don''t skip it.','The forearm should be stable — only the wrist moves during these exercises.','Do this 3x per week during active playing periods — prevention requires consistency.']::text[], ARRAY['Too much weight — causes compensation movements and injury risk.','Fast ballistic reps — the wrist extensors cannot handle rapid loading.','Only doing wrist curls and ignoring extensions — the imbalance causes tennis elbow.']::text[], ARRAY['Towel squeeze: squeeze a rolled towel as hard as possible, hold 5 seconds — grip endurance.','Pronation and supination: rotate the wrist palm up to palm down with a light weight.','Finger ladder: stretch rubber bands with increasing resistance using the fingers.']::text[], ARRAY['fitness','wrist','forearm','beginner','injury prevention','tennis elbow']::text[], 'json', '{"p1":{"x":200,"y":850},"areas":[{"x":200,"y":850,"r":20}]}'::jsonb),
  ('FT-017', 'Multi-Ball Chase Fitness: Continuous Pressure', 'Fitness', 'Aerobic Conditioning', 'fitness', 'advanced', 15, 2, 'pairs', 'Build maximum aerobic capacity and stroke quality under extreme fatigue through continuous multi-ball feeding. Player 2 feeds balls in rapid succession to all areas of the court — Player 1 must reach and hit every ball. This drill combines the physical demand of maximum cardiovascular fitness with the technical demand of maintaining stroke quality under fatigue — the exact challenge of the third set of a competitive match.', 'Build maximum aerobic capacity and stroke quality under extreme fatigue through continuous multi-ball feeding. Player 2 feeds balls in rapid succession to all areas of the court — Player 1 must reach and hit every ball. This drill combines the physical demand of maximum cardiovascular fitness with the technical demand of maintaining stroke quality under fatigue — the exact challenge of the third set of a competitive match.', 'Player 2 stands at the net with a large basket of 30+ balls. Player 1 is at the baseline. Player 2 feeds balls every 3-4 seconds to random positions. Player 1 must hit every ball.', ARRAY['Player 2 feeds a ball to a random position on Player 1''s side every 3-4 seconds.','Player 1 must reach and hit every ball — quality matters, but staying alive matters more.','If Player 1 misses a ball, they continue to the next — no stopping.','Complete the full basket without rest. That is 1 round.','Rest 2 minutes. Complete 3 rounds. Track how many balls Player 1 reached in each round.']::text[], ARRAY['Split step before every ball — don''t skip it even when exhausted.','Shorten the swing under fatigue — compact swings are more reliable.','Breathe on every contact — don''t hold your breath during sprints.','Recovery to center after every ball — even if imperfect, always recover.','Mental focus: each ball is a fresh start. Don''t think about the balls you missed.']::text[], ARRAY['Giving up on far balls — always try to reach every ball.','Stopping to rest mid-basket — the fitness demand requires continuous movement.','Dropping the split step after 15 balls — the drill reveals exactly when footwork breaks down.']::text[], ARRAY['Targeted multi-ball: Player 1 must return all balls cross-court only — adds placement under fatigue.','Race the basket: how many balls in a 30-ball basket can Player 1 hit in the court? Track weekly.','Two-on-one: two feeders — one at each corner of the net — maximum coverage demand.']::text[], ARRAY['fitness','multi-ball','aerobic','advanced','fatigue','match-simulation']::text[], 'json', '{"p1":{"x":200,"y":850},"p2":{"x":200,"y":480},"shots":[{"x1":200,"y1":490,"x2":65,"y2":840},{"x1":200,"y1":490,"x2":335,"y2":840},{"x1":200,"y1":490,"x2":200,"y2":660},{"x1":200,"y1":490,"x2":200,"y2":840}],"moves":[{"x1":200,"y1":850,"x2":65,"y2":850},{"x1":65,"y1":850,"x2":200,"y2":850},{"x1":200,"y1":850,"x2":335,"y2":850}]}'::jsonb),
  ('FT-018', 'Hip Flexor and Quad Mobility: Pre-Match Protocol', 'Fitness', 'Mobility', 'fitness', 'beginner', 10, 1, 'individual', 'Develop a systematic pre-match mobility routine targeting the hip flexors and quadriceps — the two muscle groups most affected by the repetitive lunge and sprint demands of tennis. Tight hip flexors reduce stride length and lateral range of motion. Tight quads increase knee injury risk. This routine takes 10 minutes and should be performed before every practice or match.', 'Develop a systematic pre-match mobility routine targeting the hip flexors and quadriceps — the two muscle groups most affected by the repetitive lunge and sprint demands of tennis. Tight hip flexors reduce stride length and lateral range of motion. Tight quads increase knee injury risk. This routine takes 10 minutes and should be performed before every practice or match.', 'Player 1 needs only the court surface or a mat. No equipment required. The routine covers 5 movements, held for appropriate durations.', ARRAY['Hip flexor lunge stretch: deep lunge, back knee on ground, hold 45 seconds each side.','Dynamic hip circles: standing on one leg, circle the opposite hip — 10 circles each direction, each leg.','Quad stretch: standing, pull heel to glute — hold 30 seconds each side.','Walking lunge with twist: forward lunge and rotate the torso toward the front leg — 8 reps each side.','Lateral leg swing: hold a fence, swing the leg sideways across the body — 12 swings each leg.','Complete the full sequence once. On match days, repeat twice.']::text[], ARRAY['The hip flexor lunge is the most important exercise — hold it with a slight anterior pelvic tilt.','Dynamic movements should be controlled, not ballistic — mobility, not stretching.','Breathe into each stretch — exhale to deepen the position.','The walking lunge with twist activates the hip and core simultaneously — do it last.','This routine should be done warm — light cardio for 5 minutes before stretching.']::text[], ARRAY['Stretching cold — static stretching cold muscles is dangerous.','Rushing the stretches — each position needs at least 30 seconds to take effect.','Forgetting this before matches — this is not optional for injury prevention.']::text[], ARRAY['Add a foam roller: roll the quads and hip flexors before the stretch sequence.','Post-match version: static holds longer (60 seconds) — recovery focus.','Partner-assisted stretch: Player 2 assists the hip flexor stretch into deeper range.']::text[], ARRAY['fitness','mobility','hip flexor','beginner','pre-match','injury prevention']::text[], 'json', '{"p1":{"x":200,"y":850},"areas":[{"x":200,"y":850,"r":30}]}'::jsonb),
  ('FT-019', 'Cone Shuffle and Sprint Combination: Match Movement', 'Fitness', 'Agility', 'fitness', 'intermediate', 12, 1, 'individual', 'Build the combination of lateral agility and forward sprint — the two most common movement sequences in tennis. Most on-court movements combine lateral movement (to reach the ball) with a forward element (to attack a short ball) or a backward element (to retrieve a deep ball). This drill trains the physical transition between lateral and directional movement.', 'Build the combination of lateral agility and forward sprint — the two most common movement sequences in tennis. Most on-court movements combine lateral movement (to reach the ball) with a forward element (to attack a short ball) or a backward element (to retrieve a deep ball). This drill trains the physical transition between lateral and directional movement.', 'Place 3 cones in a triangle: cone A at center baseline, cone B 8 feet to the right, cone C 8 feet forward and right of center. Player 1 shuffles from A to B, sprints diagonally to C, then backpedals back to A.', ARRAY['Start at cone A (center baseline).','Lateral shuffle from A to B (8 feet right) — touch cone B.','Sprint diagonally forward from B to C — touch cone C.','Backpedal diagonally from C back to A — touch cone A.','That is 1 rep. Complete 8 reps per set. Rest 45 seconds. Play 4 sets.']::text[], ARRAY['The shuffle must be genuine — don''t crossover during the lateral segment.','Sprint explosively from B to C — this is the attack move after reaching the ball.','Backpedal from C to A using crossover steps — faster than a true backpedal.','Stay low throughout all three movement phases — no standing up between segments.','Touch each cone fully — the touch forces a complete deceleration before each direction change.']::text[], ARRAY['Crossing feet during the lateral shuffle — technically incorrect and slower.','Slow sprint from B to C — should be maximum effort.','Regular backpedal from C to A instead of crossover — slower.']::text[], ARRAY['Mirror triangle: repeat on the left side — cone B to the left.','Reverse triangle: sprint from A to C, shuffle C to B, backpedal B to A.','Racket in hand: perform the full pattern while carrying a racket in the ready position.']::text[], ARRAY['fitness','agility','cone','intermediate','combination','movement']::text[], 'json', '{"p1":{"x":200,"y":850},"moves":[{"x1":200,"y1":850,"x2":295,"y2":850},{"x1":295,"y1":850,"x2":295,"y2":720},{"x1":295,"y1":720,"x2":200,"y2":850}],"cones":[{"x":200,"y":850},{"x":295,"y":850},{"x":295,"y":720}]}'::jsonb),
  ('FT-020', 'Calf Raise and Jump Complex: Lower Leg Power', 'Fitness', 'Explosive Power', 'fitness', 'beginner', 10, 1, 'individual', 'Build calf strength and explosive ankle power through a calf raise and jump complex. The calves and ankles are the final link in the leg power chain — they are the last muscles to push off the ground before any tennis movement. Strong calves maintain the on-toes position required for split steps and quick first steps throughout an entire match.', 'Build calf strength and explosive ankle power through a calf raise and jump complex. The calves and ankles are the final link in the leg power chain — they are the last muscles to push off the ground before any tennis movement. Strong calves maintain the on-toes position required for split steps and quick first steps throughout an entire match.', 'Player 1 uses a step or the edge of the baseline if on court. A step provides a greater range of motion for the calves. No additional equipment needed.', ARRAY['Stand on the edge of a step with heels hanging off — toes and ball of foot on the step.','Lower the heels as far as possible (calf stretch at the bottom).','Rise to maximum height on the toes.','Complete 20 slow calf raises per set. Rest 30 seconds.','After 2 sets of slow raises, transition to 2 sets of explosive calf jumps — both feet, maximum height, 10 reps.']::text[], ARRAY['Full range of motion — lower as far as the heel allows, rise as high as possible.','Slow on the way down — eccentric loading builds more strength than concentric.','On the jump complex: land on the balls of the feet and immediately re-launch — minimal ground contact.','Single-leg version: one foot on the step — dramatically increases the load.','Feel the difference between a flat-footed and toe-raised position — the toe position is faster.']::text[], ARRAY['Short range of motion — not lowering or rising fully.','Flat-footed jumps — defeats the purpose of the calf complex.','Slow jumps — must be explosive to train the fast-twitch calf fibers.']::text[], ARRAY['Single-leg calf raise: one leg only — doubles the resistance.','Weighted calf raise: hold a dumbbell — progressive resistance.','Jump rope in sets of 100: supersedes calf raises for calf endurance.']::text[], ARRAY['fitness','calf','jump','beginner','lower leg','explosive']::text[], 'json', '{"p1":{"x":200,"y":850},"moves":[{"x1":200,"y1":850,"x2":200,"y2":820},{"x1":200,"y1":820,"x2":200,"y2":850}],"areas":[{"x":200,"y":835,"r":20}]}'::jsonb),
  ('FT-021', 'Serve Power Circuit: Kinetic Chain Training', 'Fitness', 'Strength', 'fitness', 'intermediate', 15, 1, 'individual', 'Develop the complete kinetic chain for the serve through a targeted circuit that trains every segment involved: legs (for drive), core (for transfer), shoulder (for rotation), and arm (for whip). The serve is a full-body movement and training it segment by segment before integrating the full swing creates greater power than practicing the serve alone.', 'Develop the complete kinetic chain for the serve through a targeted circuit that trains every segment involved: legs (for drive), core (for transfer), shoulder (for rotation), and arm (for whip). The serve is a full-body movement and training it segment by segment before integrating the full swing creates greater power than practicing the serve alone.', 'Player 1 uses a resistance band, light dumbbells (2-4kg), and a medicine ball (2-3kg). The circuit rotates through 4 exercises targeting each kinetic chain segment.', ARRAY['Squat jump: 3 x 8 — explosive leg drive, simulates the serve leg launch.','Overhead medicine ball slam: 3 x 8 — full body rotation into an overhead slam.','Resistance band internal/external shoulder rotation: 3 x 15 each direction.','Wrist snap with light dumbbell: 3 x 20 — hold dumbbell, pronate/supinate the wrist rapidly.','Rest 45 seconds between exercises. Complete 2 full circuit rotations.']::text[], ARRAY['Each exercise is a segment of the serve — think about the serve connection as you do each one.','The squat jump trains the leg drive that launches the serve.','The overhead slam trains the same overhead path as the racket on contact.','The wrist snap is the final acceleration of the serve — it adds 5-10 mph.','Integrate: after the circuit, hit 10 serves immediately — the activated kinetic chain transfers.']::text[], ARRAY['Training the segments in isolation without hitting serves immediately after — misses the integration.','Overhead slam: using the arms only — must involve hip rotation.','Wrist snap: too heavy a dumbbell — risks wrist injury.']::text[], ARRAY['Band-resisted serve: attach a light band to the wrist and practice the serve motion.','Weighted racket serve: practice serves with a weighted racket cover — builds arm strength.','Contrast method: 3 circuit exercises then 5 serves — alternate between strength and skill.']::text[], ARRAY['fitness','serve','kinetic chain','intermediate','power','strength']::text[], 'json', '{"p1":{"x":240,"y":860},"shots":[{"x1":240,"y1":850,"x2":200,"y2":378}],"areas":[{"x":240,"y":860,"r":25}]}'::jsonb),
  ('FT-022', 'Breathing Protocol: Controlled Recovery Between Points', 'Fitness', 'Recovery', 'fitness', 'beginner', 10, 1, 'individual', 'Develop a systematic breathing protocol for the 20-second rest between points — the most underutilized recovery tool in tennis. Most players waste the between-point time by tension-holding, rapid shallow breathing, or mentally replaying errors. A controlled breathing protocol restores oxygen faster, reduces heart rate more quickly, and clears the mind for the next point. It is a physical and mental fitness skill.', 'Develop a systematic breathing protocol for the 20-second rest between points — the most underutilized recovery tool in tennis. Most players waste the between-point time by tension-holding, rapid shallow breathing, or mentally replaying errors. A controlled breathing protocol restores oxygen faster, reduces heart rate more quickly, and clears the mind for the next point. It is a physical and mental fitness skill.', 'Player 1 can practice this between any rally sequences or in isolation. A timer set for 20 seconds represents the between-point rest.', ARRAY['After a point ends, turn away from the net — face the back fence.','Exhale completely — push all air out of the lungs.','Inhale for 4 counts through the nose — deep belly breath, not chest breath.','Hold for 2 counts.','Exhale for 6 counts through the mouth — controlled, slow.','Repeat 2 times within the 20-second window.','On the 20th second, turn back to the baseline ready to serve or return.']::text[], ARRAY['The 4-2-6 ratio is the optimal recovery breathing pattern — proven to reduce heart rate fastest.','Belly breathing (diaphragm) is more efficient than chest breathing — lower the shoulders.','Facing away from the net during breathing is not optional — it separates the point that was from the point ahead.','The exhale is where the heart rate drops — prioritize it over the inhale.','Practice this in non-pressure situations so it becomes automatic under pressure.']::text[], ARRAY['Shallow chest breathing — barely increases oxygen intake.','Looking at the opponent during recovery — extends the mental engagement with the previous point.','Not using the full 20 seconds — every second of controlled breathing has value.']::text[], ARRAY['Box breathing: 4-4-4-4 (inhale, hold, exhale, hold) — stronger mental reset.','Post-rally practice: after every rally in practice, perform 2 cycles before the next ball.','Under pressure: specifically practice the protocol at deuce and ad-out — high-pressure simulation.']::text[], ARRAY['fitness','breathing','recovery','beginner','mental','between points']::text[], 'json', '{"p1":{"x":200,"y":850},"areas":[{"x":200,"y":850,"r":20}]}'::jsonb),
  ('FT-023', 'Deceleration Training: Stop on a Dime', 'Fitness', 'Strength', 'fitness', 'intermediate', 12, 1, 'individual', 'Build deceleration strength — the ability to stop rapidly from full sprint without losing balance or joint integrity. Deceleration injuries (ACL, hamstring tears) occur most commonly when a player cannot absorb the forces of stopping quickly. Training deceleration specifically reduces injury risk and simultaneously improves the ability to change direction, which requires a complete stop before re-acceleration.', 'Build deceleration strength — the ability to stop rapidly from full sprint without losing balance or joint integrity. Deceleration injuries (ACL, hamstring tears) occur most commonly when a player cannot absorb the forces of stopping quickly. Training deceleration specifically reduces injury risk and simultaneously improves the ability to change direction, which requires a complete stop before re-acceleration.', 'Player 1 sprints on the court between cones. The drill uses progressive deceleration distances — starting with 3 steps to stop, progressing to 1 step to stop as strength improves.', ARRAY['Sprint from baseline to service line at full pace.','At the service line cone, decelerate and stop in exactly 3 steps.','Hold the stopped position for 1 second — check balance.','Sprint back to baseline, decelerate in 3 steps, hold.','After 5 reps at 3 steps, progress to 2 steps. After 5 more, progress to 1 step.','1-step stop: full sprint, plant both feet simultaneously on the line — extreme deceleration demand.']::text[], ARRAY['Lower the hips as you decelerate — high-body deceleration puts all stress on the knees.','Widen the base on the final step — wider feet create more braking surface.','The arms pull back during deceleration — they act as a brake.','1-step stop requires very strong quads and glutes — only progress when 3-step is controlled.','The held position must be balanced — any stumbling means deceleration was not under control.']::text[], ARRAY['Deceleration only through the upper body — upper body leans back while lower body continues forward.','No hip drop — joints absorb all the force without muscular assist.','Skipping the hold — the held position confirms control.']::text[], ARRAY['Lateral deceleration: sprint laterally and stop in 1-3 steps.','Stop and go: decelerate completely, then immediately re-accelerate — tests reactive power.','Sloped surface: practice decelerating on a slight downhill — increases the challenge.']::text[], ARRAY['fitness','deceleration','strength','intermediate','injury prevention','stopping']::text[], 'json', '{"p1":{"x":200,"y":670},"p2":{"x":200,"y":480},"moves":[{"x1":200,"y1":850,"x2":200,"y2":670},{"x1":200,"y1":670,"x2":200,"y2":850}],"cones":[{"x":200,"y":670},{"x":200,"y":850}]}'::jsonb),
  ('FT-024', 'Long-Distance Court Run: Aerobic Base Building', 'Fitness', 'Aerobic Conditioning', 'fitness', 'beginner', 20, 1, 'individual', 'Build the aerobic base — the fundamental cardiovascular fitness layer that supports all tennis-specific conditioning. Many club players lack sufficient aerobic base, causing them to fatigue early in matches and lose concentration. A strong aerobic base allows the body to recover more quickly between points and sets, sustain quality in the third set, and maintain tactical thinking under physical stress.', 'Build the aerobic base — the fundamental cardiovascular fitness layer that supports all tennis-specific conditioning. Many club players lack sufficient aerobic base, causing them to fatigue early in matches and lose concentration. A strong aerobic base allows the body to recover more quickly between points and sets, sustain quality in the third set, and maintain tactical thinking under physical stress.', 'Player 1 runs around the perimeter of the court (or a larger area) at a steady, conversational pace. This is not a sprint — it is a sustained, moderate-effort run. Target heart rate: 60-70% of maximum (you should be able to speak in full sentences).', ARRAY['Run continuously at a comfortable conversational pace for 20 minutes.','Maintain a pace where you could speak full sentences — not gasping.','If the court is too small, run around 3-4 courts or a nearby running area.','Keep pace consistent throughout — not faster at the start, not slower at the end.','After the run, note the heart rate — should be 120-140 BPM for most adults.']::text[], ARRAY['If you cannot speak, you are running too fast — slow down.','Consistent pace is the goal — this is base building, not interval training.','Land on the mid-foot — reduces impact forces compared to heel striking.','Breathe through the nose if possible — develops breathing efficiency.','This run should feel easy — the fitness comes from the duration, not the intensity.']::text[], ARRAY['Running too fast — turns it into an interval run, misses the aerobic base stimulus.','Too short — 20 minutes is the minimum for aerobic base stimulus.','Only doing this occasionally — aerobic base requires 3 runs per week to develop.']::text[], ARRAY['Increase duration progressively: 20 minutes → 25 → 30 over 3 weeks.','Fartlek: add 30-second surges every 5 minutes — maintains aerobic base while adding intensity.','Tennis-specific run: alternate 1 lap of jogging with 1 lap of lateral shuffles.']::text[], ARRAY['fitness','aerobic','base building','beginner','endurance','cardiovascular']::text[], 'json', '{"p1":{"x":200,"y":850},"moves":[{"x1":65,"y1":850,"x2":335,"y2":850},{"x1":335,"y1":850,"x2":335,"y2":70},{"x1":335,"y1":70,"x2":65,"y2":70},{"x1":65,"y1":70,"x2":65,"y2":850}]}'::jsonb),
  ('FT-025', 'Romanian Deadlift to Row: Posterior Chain Power', 'Fitness', 'Strength', 'fitness', 'intermediate', 12, 1, 'individual', 'Strengthen the entire posterior chain — hamstrings, glutes, lower back, and upper back — through the Romanian deadlift to row combination. The posterior chain is the engine of all forward sprints, change-of-direction power, and the pulling motion of the backhand. A strong posterior chain also protects the lower back from the rotational stresses of match play.', 'Strengthen the entire posterior chain — hamstrings, glutes, lower back, and upper back — through the Romanian deadlift to row combination. The posterior chain is the engine of all forward sprints, change-of-direction power, and the pulling motion of the backhand. A strong posterior chain also protects the lower back from the rotational stresses of match play.', 'Player 1 uses a barbell (preferred) or two dumbbells (10-20kg each, adjust to fitness level). Proper technique is mandatory — lighter is better than heavy with bad form.', ARRAY['Stand with feet hip-width apart, holding the dumbbells.','Hinge at the hips, lower the dumbbells down the shins — straight back, soft knees.','At the bottom, perform a bent-over row: pull the dumbbells to the hips — squeeze the back.','Lower the row back to the hanging position.','Drive through the heels to stand upright — squeeze the glutes at the top.','Complete 8 reps per set. Rest 60 seconds. Play 4 sets.']::text[], ARRAY['The back must stay straight throughout — rounding is the most common error.','Row at the bottom — not at the top. The row happens when the torso is at 45 degrees.','Drive through the heels to stand — not through the toes.','Squeeze the glutes at the top — full hip extension is required.','This exercise is harder than it looks — start lighter than you think is necessary.']::text[], ARRAY['Rounding the back during the hinge — risk of lower back injury.','Row at the wrong position — rowing at the top or during the hinge loses the movement sequencing.','Partial hip extension at the top — not squeezing the glutes.']::text[], ARRAY['Single-arm dumbbell RDL to row: unilateral version — more balance demand.','Band RDL to row: resistance band under the feet — gentle starting version.','RDL only: remove the row if the combined movement is too complex initially.']::text[], ARRAY['fitness','deadlift','posterior chain','intermediate','strength','back']::text[], 'json', '{"p1":{"x":200,"y":850},"areas":[{"x":200,"y":850,"r":25}]}'::jsonb),
  ('FT-026', 'Mental Toughness Drill: Play Through Physical Discomfort', 'Fitness', 'Mental Fitness', 'fitness', 'advanced', 20, 2, 'pairs', 'Build mental toughness by deliberately training through physical discomfort — the most direct preparation for the third set of a close competitive match. Most competitive matches are decided not by technique but by who can sustain quality under fatigue and discomfort. This drill creates genuine physical fatigue before each point and requires Players to continue competing at full quality despite the discomfort.', 'Build mental toughness by deliberately training through physical discomfort — the most direct preparation for the third set of a close competitive match. Most competitive matches are decided not by technique but by who can sustain quality under fatigue and discomfort. This drill creates genuine physical fatigue before each point and requires Players to continue competing at full quality despite the discomfort.', 'Player 1 and Player 2 alternate serving and returning. Before every single point, the serving player does 5 squat jumps. Before every return, the returning player does 5 lateral bounds. Then the point is played normally.', ARRAY['Before every serve: server does 5 squat jumps immediately before tossing.','Before every return: returner does 5 lateral bounds immediately before the serve is hit.','Play the full point with genuine competitive intensity despite the physical load.','Play 15 consecutive points without stopping — the fatigue compounds.','Track score — winning while physically fatigued is the training goal.']::text[], ARRAY['The physical load is the point — embrace the discomfort rather than fighting it.','Maintain technique and tactical decisions despite fatigue — this is the drill''s objective.','Breathe between the physical load and the point — use the serve routine to recover.','Notice which aspects of your game degrade first under fatigue — those need targeted work.','After the drill, ask: what score would you have if you felt fresh? The gap reveals the mental fitness work needed.']::text[], ARRAY['Not completing the full squat jump or bound load — cheating defeats the purpose.','Giving up competitive intensity after fatigue builds — the competitive intensity is the mental training.','Not tracking the score — the score creates the competitive pressure.']::text[], ARRAY['Increase the pre-point load: 10 squat jumps instead of 5 — more fatigue.','Staggered load: one player has the load, the other doesn''t — simulates playing a fitter opponent.','Changeover: add 20 squat jumps at each changeover — compounds the fatigue over time.']::text[], ARRAY['fitness','mental toughness','advanced','fatigue','competition','resilience']::text[], 'json', '{"p1":{"x":280,"y":850},"p2":{"x":120,"y":60},"shots":[{"x1":240,"y1":855,"x2":200,"y2":375},{"x1":120,"y1":70,"x2":275,"y2":830},{"x1":275,"y1":840,"x2":100,"y2":100}],"areas":[{"x":280,"y":850,"r":20},{"x":120,"y":60,"r":20}]}'::jsonb),
  ('FT-027', 'Ankle Stability and Proprioception: Court Surface Training', 'Fitness', 'Injury Prevention', 'fitness', 'beginner', 12, 1, 'individual', 'Build ankle stability and proprioception to prevent the most common tennis injury: the ankle sprain. Tennis players change direction hundreds of times per match on surfaces that vary from hard to clay to grass. Ankle sprains occur when the ankle is loaded in an unstable position. This circuit trains the ankle stabilizing muscles to activate automatically under unexpected loads.', 'Build ankle stability and proprioception to prevent the most common tennis injury: the ankle sprain. Tennis players change direction hundreds of times per match on surfaces that vary from hard to clay to grass. Ankle sprains occur when the ankle is loaded in an unstable position. This circuit trains the ankle stabilizing muscles to activate automatically under unexpected loads.', 'Player 1 needs only the court surface. Optional: a wobble board or Bosu ball for advanced progressions. The circuit is performed in barefoot or minimalist shoes for maximum proprioceptive feedback.', ARRAY['Single-leg balance: stand on one foot with eyes open — hold 30 seconds each foot.','Single-leg balance with eyes closed: same position, close the eyes — 20 seconds each foot.','Single-leg calf raise: rise on the toes on one foot, lower — 15 reps each foot.','Ankle circles: lift the foot off the ground and circle the ankle — 10 circles each direction.','Single-leg hop and hold: jump off one foot, land on the same foot, hold 2 seconds — 8 reps each.','Complete the full circuit twice. Rest 30 seconds between exercises.']::text[], ARRAY['Eyes closed balance is significantly harder — the ankle stabilizers must work without visual aid.','The single-leg hop and hold simulates the landing forces of a split step — the most important exercise.','Focus on landing quality: ankle, knee, and hip all absorb the landing in sequence.','Progress each exercise only when the previous is controlled — don''t rush the progression.','This circuit should be done 3 times per week as an injury prevention routine.']::text[], ARRAY['Skipping the eyes-closed version — the visual deprivation is the training stimulus.','Landing on a stiff leg — all force goes to the joint, not the muscles.','Not holding the balance — the hold activates the stabilizers.']::text[], ARRAY['Wobble board: all exercises on a wobble board — significant proprioception challenge.','Tennis-specific hop: hop in the shape of the split step — forward, land wide.','Partner disturbance: partner gently pushes Player 1 during single-leg balance — reactive stability.']::text[], ARRAY['fitness','ankle','proprioception','beginner','injury prevention','stability']::text[], 'json', '{"p1":{"x":200,"y":850},"areas":[{"x":200,"y":850,"r":20}]}'::jsonb),
  ('FT-028', 'Ladder of Pain: Consecutive Point Fitness', 'Fitness', 'Mental Fitness', 'fitness', 'advanced', 20, 2, 'pairs', 'Build the competitive fitness to win consecutive points under cumulative fatigue — the exact demand of winning a game, a set, or a match from behind. The Ladder of Pain requires winning points in succession starting from a physical load; each missed point restarts the ladder. It trains both the physical fitness to sustain quality across consecutive efforts and the mental fitness to persevere after setbacks.', 'Build the competitive fitness to win consecutive points under cumulative fatigue — the exact demand of winning a game, a set, or a match from behind. The Ladder of Pain requires winning points in succession starting from a physical load; each missed point restarts the ladder. It trains both the physical fitness to sustain quality across consecutive efforts and the mental fitness to persevere after setbacks.', 'Player 1 must win 5 consecutive points to complete the ladder. Before each point, Player 1 does a physical load (5 squat jumps). If Player 1 loses any point, the consecutive count resets to zero — Player 1 must start over from point 1.', ARRAY['Player 1 does 5 squat jumps before each point.','Player 1 must win the point to advance up the ladder.','Player 1 must win 5 consecutive points to complete the ladder.','Any lost point resets the count to 0 — Player 1 starts the squat jumps and the count again.','The drill ends when Player 1 completes 5 consecutive wins. Track total time and total points played.']::text[], ARRAY['The reset after a loss is the mental fitness challenge — accept it and start again with full commitment.','Use the physical load time (squat jumps) to breathe and mentally reset.','Play smart tennis under fatigue — aggressive shots should only come when the position warrants them.','The late stages (points 4 and 5) are when the mental training is most intense — don''t tighten up.','A player who completes this ladder has trained both physical fitness and mental resilience.']::text[], ARRAY['Giving up mental intensity after resetting — the reset is not a punishment, it''s a training stimulus.','Not completing the full squat jump load — cheating undermines the fitness component.','Panic-hitting to win points — under fatigue, smart tennis beats aggressive tennis.']::text[], ARRAY['Ladder of 7: must win 7 consecutive — more demanding.','Two-player ladder: both players must complete their own ladders simultaneously.','Tiebreak ladder: play a tiebreak where every serve requires a pre-point physical load.']::text[], ARRAY['fitness','ladder','mental toughness','advanced','consecutive','competition']::text[], 'json', '{"p1":{"x":280,"y":850},"p2":{"x":120,"y":60},"shots":[{"x1":240,"y1":855,"x2":200,"y2":375},{"x1":120,"y1":70,"x2":280,"y2":820},{"x1":280,"y1":830,"x2":100,"y2":100}],"areas":[{"x":100,"y":100,"r":25},{"x":280,"y":850,"r":20}]}'::jsonb),
  ('FT-029', 'Yoga for Tennis: Flexibility and Recovery Session', 'Fitness', 'Mobility', 'fitness', 'beginner', 20, 1, 'individual', 'Develop tennis-specific flexibility and accelerate muscle recovery through a targeted yoga sequence. Yoga is widely used by professional tennis players (Djokovic being the most famous advocate) because it addresses the specific tightness patterns of tennis: hip flexors from serving, thoracic rotation for groundstrokes, hamstrings from sprinting, and shoulder mobility from serving. This session covers all four areas.', 'Develop tennis-specific flexibility and accelerate muscle recovery through a targeted yoga sequence. Yoga is widely used by professional tennis players (Djokovic being the most famous advocate) because it addresses the specific tightness patterns of tennis: hip flexors from serving, thoracic rotation for groundstrokes, hamstrings from sprinting, and shoulder mobility from serving. This session covers all four areas.', 'Player 1 needs a yoga mat or soft surface. The sequence takes 20 minutes and targets all the major tennis-specific tightness patterns. This session is designed for post-practice or rest days.', ARRAY['Downward dog: hold 60 seconds — stretches hamstrings, calves, and upper back.','Pigeon pose: right leg forward — hold 60 seconds. Switch to left — hold 60 seconds. Targets hip flexors.','Thread the needle: lying on back, cross right ankle over left knee, pull left knee to chest — 45 seconds each side.','Supine spinal twist: lying on back, bring right knee across to left side, arms out — 45 seconds each side.','Child''s pose with lat stretch: child''s pose, walk hands to one side — 30 seconds each side.','Repeat the full sequence once more.']::text[], ARRAY['Breathe into each pose — the exhale is what deepens the stretch.','Never force a position — discomfort is okay, pain is not.','Pigeon pose is the most important for tennis hip flexors — spend extra time here.','The spinal twist maintains thoracic rotation — important for groundstrokes.','This sequence is most effective when performed 4-5 times per week, not just once.']::text[], ARRAY['Forcing depth in poses — creates injury instead of flexibility.','Holding the breath — prevents the muscles from relaxing.','Doing yoga only after matches — should be 4-5 times per week for real benefit.']::text[], ARRAY['Yin yoga hold: hold each pose 3-5 minutes — deeper connective tissue release.','Morning yoga: lighter version first thing in the morning — mobility throughout the day.','Partner assist: partner gently assists each stretch into deeper range.']::text[], ARRAY['fitness','yoga','flexibility','beginner','recovery','mobility']::text[], 'json', '{"p1":{"x":200,"y":850},"areas":[{"x":200,"y":850,"r":30}]}'::jsonb),
  ('FT-030', 'Fitness Grand Finale: The Complete Match Fitness Test', 'Fitness', 'Assessment', 'fitness', 'advanced', 25, 2, 'pairs', 'Assess and stress-test complete match fitness through a comprehensive simulation that combines all physical components: explosive power, aerobic endurance, deceleration, court coverage, and mental toughness under fatigue. This drill is a fitness assessment — the results reveal exactly which fitness components limit match performance and require priority in the next training block.', 'Assess and stress-test complete match fitness through a comprehensive simulation that combines all physical components: explosive power, aerobic endurance, deceleration, court coverage, and mental toughness under fatigue. This drill is a fitness assessment — the results reveal exactly which fitness components limit match performance and require priority in the next training block.', 'A structured 25-minute fitness circuit combining all the key physical demands of match play. Both players participate and track all data. Assessment categories: sprint speed, lateral speed, aerobic capacity, and match play quality under fatigue.', ARRAY['Phase 1 (5 min): Spider run test — time 3 complete spider runs. Record time.','Phase 2 (5 min): 30-30 rally protocol — 5 rounds of 30 seconds rallying, 30 seconds rest.','Phase 3 (5 min): Multi-ball chase — full basket of 25 balls, record how many Player 1 reaches.','Phase 4 (5 min): Baseline suicide run — 3 complete suicides, record time.','Phase 5 (5 min): Competitive points under fatigue — play 10 points immediately after Phase 4.','Record all data. Compare across sessions monthly.']::text[], ARRAY['Phase 1 reveals footwork speed and deceleration quality — slow times mean footwork needs work.','Phase 2 reveals aerobic fitness — quality degradation reveals the aerobic ceiling.','Phase 3 reveals court coverage — missed balls late in the basket reveal the fitness gap.','Phase 4 reveals conditioning level — time degradation reveals anaerobic capacity.','Phase 5 reveals mental fitness — competitive quality under fatigue is the ultimate measure.']::text[], ARRAY['Not recording the data — the assessment only has value if results are tracked and compared.','Not going all-out in each phase — the assessment requires genuine maximum effort.','Doing the assessment when fresh — it should be done mid-practice, not at the start.']::text[], ARRAY['Monthly assessment: repeat every 4 weeks — chart fitness improvement.','Peer comparison: both players complete all 5 phases simultaneously — compare profiles.','Weakest link training: identify the phase with the worst score, train it specifically for 4 weeks, retest.']::text[], ARRAY['fitness','assessment','comprehensive','advanced','match-simulation','fitness test']::text[], 'json', '{"p1":{"x":200,"y":850},"p2":{"x":200,"y":60},"moves":[{"x1":200,"y1":850,"x2":200,"y2":480},{"x1":200,"y1":480,"x2":65,"y2":480},{"x1":65,"y1":480,"x2":65,"y2":850},{"x1":65,"y1":850,"x2":335,"y2":850},{"x1":335,"y1":850,"x2":335,"y2":480}],"cones":[{"x":200,"y":480},{"x":65,"y":480},{"x":335,"y":480},{"x":65,"y":850},{"x":335,"y":850}],"shots":[{"x1":280,"y1":840,"x2":110,"y2":90},{"x1":120,"y1":70,"x2":275,"y2":830}]}'::jsonb),
  ('FW-001', 'Split Step Isolation: Timing to a Visual Cue', 'Footwork', 'Split Step', 'footwork', 'beginner', 10, 2, 'pairs', 'Isolate and train the split step with perfect timing using a visual cue. The split step is the most important single movement in tennis — it loads the legs and allows the player to explode in any direction. Yet most players either skip it entirely or perform it at the wrong time. This drill builds the split step as an automatic, correctly-timed reflex rather than a conscious decision.', 'Isolate and train the split step with perfect timing using a visual cue. The split step is the most important single movement in tennis — it loads the legs and allows the player to explode in any direction. Yet most players either skip it entirely or perform it at the wrong time. This drill builds the split step as an automatic, correctly-timed reflex rather than a conscious decision.', 'Player 1 stands at the baseline in the ready position. Player 2 stands across the net and simply raises their racket to signal the trigger. Player 1 split steps the moment Player 2''s racket reaches the contact point. No balls are hit — this drill is purely footwork.', ARRAY['Player 1 stands at the center baseline in the athletic ready position: knees bent, weight on balls of feet, racket centered.','Player 2 performs a slow-motion serve or groundstroke swing from across the net.','Player 1 must split step exactly as Player 2''s racket reaches the point of contact with an imaginary ball.','After the split step, Player 1 takes one explosive first step in a called direction: left, right, forward, or back.','Repeat 20 times. Focus entirely on split step timing — not the first step direction.']::text[], ARRAY['The split step is a small, quick hop — not a large jump. 2-3 inches off the ground is enough.','Land softly on the balls of both feet simultaneously — heels never touch.','Land with knees slightly bent and body coiled — the landing position IS the explosive launch position.','The trigger is the opponent''s contact — not the backswing, not the follow-through.','After landing, the first step must happen within 0.1 seconds — the split step loads the spring.']::text[], ARRAY['Splitting on the backswing — too early, lands flat before the ball direction is clear.','Splitting after the ball has passed — too late, no time to react.','Large jump — heavy landing kills the reactive energy instead of storing it.','Flat-footed landing — cannot redirect from a heel-down landing.']::text[], ARRAY['Sound cue: Player 2 claps instead of swinging — Player 1 splits on the clap sound.','Multiple split steps: Player 2 swings three times in a row — Player 1 splits on each contact.','Moving split step: Player 1 walks toward the net — must split step mid-movement on the cue.']::text[], ARRAY['footwork','split step','beginner','timing','foundation','movement']::text[], 'json', '{"p1":{"x":200,"y":850},"p2":{"x":200,"y":60},"moves":[{"x1":200,"y1":850,"x2":240,"y2":850},{"x1":240,"y1":850,"x2":200,"y2":850},{"x1":200,"y1":850,"x2":160,"y2":850}],"areas":[{"x":200,"y":850,"r":25}]}'::jsonb),
  ('FW-002', 'Lateral Shuffle: Side to Side Baseline Coverage', 'Footwork', 'Lateral Movement', 'footwork', 'beginner', 10, 1, 'individual', 'Build the lateral shuffle — the primary movement pattern for covering the baseline. The lateral shuffle keeps the player facing the net at all times, maintains a low center of gravity, and allows rapid changes of direction. It is used to cover the vast majority of groundstrokes hit to the baseline. This drill builds the shuffle as a physical habit through pure repetition.', 'Build the lateral shuffle — the primary movement pattern for covering the baseline. The lateral shuffle keeps the player facing the net at all times, maintains a low center of gravity, and allows rapid changes of direction. It is used to cover the vast majority of groundstrokes hit to the baseline. This drill builds the shuffle as a physical habit through pure repetition.', 'Player 1 stands at the center baseline. Two cones are placed 8 feet to the left and right of center — marking the forehand and backhand coverage zones. Player 1 shuffles between the cones without crossing their feet.', ARRAY['Place a cone 8 feet to the left and right of the center baseline mark.','Player 1 starts at center, shuffles to the right cone, touches it, shuffles back to center, shuffles to the left cone, touches it, returns to center.','Keep the feet from crossing — pure lateral shuffle with no crossover steps.','Complete 10 full side-to-side sequences without stopping.','Rest 30 seconds. Repeat 4 rounds. Increase the cone distance by 2 feet each round.']::text[], ARRAY['Stay low throughout — knees bent, hips lower than normal standing height.','Push off the outside foot to initiate each shuffle — drive off the foot furthest from the target.','Keep the feet parallel to the baseline — no angling the feet toward the cones.','Racket up and in front at all times — simulate the ready position throughout.','Never cross the feet — crossing leads to stumbling and slower direction changes.']::text[], ARRAY['Crossing the feet during the shuffle — trips up the movement and slows direction changes.','Standing upright — the shuffle loses its low, reactive quality when the body is tall.','Dragging the back foot — the feet must move together, not one at a time.']::text[], ARRAY['Faster pace: increase the speed of the shuffle until the maximum controllable pace is found.','Wider cones: place cones at the doubles sidelines — full court lateral coverage.','Shuffle and swing: after reaching each cone, Player 1 performs a shadow forehand or backhand swing.']::text[], ARRAY['footwork','lateral shuffle','beginner','baseline coverage','movement pattern']::text[], 'json', '{"p1":{"x":200,"y":850},"moves":[{"x1":200,"y1":850,"x2":310,"y2":850},{"x1":310,"y1":850,"x2":200,"y2":850},{"x1":200,"y1":850,"x2":90,"y2":850},{"x1":90,"y1":850,"x2":200,"y2":850}],"cones":[{"x":310,"y":850},{"x":90,"y":850}]}'::jsonb),
  ('FW-003', 'First Step Explosiveness: React and Go', 'Footwork', 'First Step', 'footwork', 'beginner', 10, 2, 'pairs', 'Build explosive first step speed — the single most important physical quality for court coverage in tennis. The first step after the split step determines how quickly a player reaches the ball. A slow first step cannot be compensated for with a fast sprint because the ball waits for no one. This drill specifically isolates and trains the explosiveness of that first directional step.', 'Build explosive first step speed — the single most important physical quality for court coverage in tennis. The first step after the split step determines how quickly a player reaches the ball. A slow first step cannot be compensated for with a fast sprint because the ball waits for no one. This drill specifically isolates and trains the explosiveness of that first directional step.', 'Player 1 stands at the center baseline in the ready position. Player 2 points in a direction — left, right, forward, or back — and Player 1 must react with an explosive first step in that direction. The emphasis is on the speed of the first step, not on covering any particular distance.', ARRAY['Player 1 stands at center baseline in the ready position.','Player 2 points a direction: left, right, forward, or backward.','Player 1 must take an explosive first step in the pointed direction within 0.2 seconds.','After the first step, Player 1 takes 2-3 more steps in the same direction, then returns to center.','Repeat 20 times. Rest 45 seconds. Play 4 rounds.']::text[], ARRAY['The first step is an explosive push, not a lift — drive off the ground like a sprinter.','Lead with the foot closest to the target direction — don''t step across.','Stay low during the first step — driving up wastes energy that should go horizontal.','Arms drive the first step — pump the opposite arm to create momentum.','The first step covers 2-3 feet, not 6 inches — commit to a real explosive movement.']::text[], ARRAY['Taking a small, tentative first step — covers too little ground.','Stepping up instead of out — wastes energy going vertical.','Slow reaction — daydreaming between points is the enemy of first step speed.']::text[], ARRAY['Eyes-closed start: Player 1 closes eyes, Player 2 calls the direction — trains auditory reaction.','Add the swing: after the first step, Player 1 performs a shadow groundstroke.','Fastest first step competition: Player 2 times with a stopwatch — Player 1 tries to beat their own record.']::text[], ARRAY['footwork','first step','explosiveness','beginner','reaction','speed']::text[], 'json', '{"p1":{"x":200,"y":850},"p2":{"x":200,"y":480},"moves":[{"x1":200,"y1":850,"x2":300,"y2":840},{"x1":200,"y1":850,"x2":100,"y2":840},{"x1":200,"y1":850,"x2":200,"y2":750}],"areas":[{"x":200,"y":850,"r":20}]}'::jsonb),
  ('FW-004', 'Crossover Step: Covering Wide Balls Fast', 'Footwork', 'Lateral Movement', 'footwork', 'intermediate', 10, 2, 'pairs', 'Develop the crossover step — the fastest footwork technique for covering wide balls. When a ball is hit further than the shuffle can reach, the crossover step is used: the far foot crosses over the near foot, launching the body explosively in the target direction. The crossover covers 2-3 times more ground per step than the shuffle and is essential for reaching wide balls in time.', 'Develop the crossover step — the fastest footwork technique for covering wide balls. When a ball is hit further than the shuffle can reach, the crossover step is used: the far foot crosses over the near foot, launching the body explosively in the target direction. The crossover covers 2-3 times more ground per step than the shuffle and is essential for reaching wide balls in time.', 'Player 1 stands at the center baseline. Player 2 feeds wide balls — beyond the reach of a normal shuffle. Player 1 must use crossover steps to reach each wide ball and shadow-swing at the contact point.', ARRAY['Player 2 feeds a wide ball to Player 1''s forehand side — further than a shuffle can reach.','Player 1 initiates with a crossover step: right foot crosses over left (for right-handers moving right).','Player 1 sprints to the wide position using crossover steps.','Player 1 shadow-swings at the imaginary ball, then recovery-sprints back to center.','Alternate wide forehand and wide backhand crossovers. Repeat 15 times each side.']::text[], ARRAY['The crossover step starts with the far foot crossing over the near foot — not the near foot stepping out.','Turn the hips in the direction of movement during the crossover — the whole body turns.','After the crossover, run normally — the crossover launches you, then sprint footwork takes over.','Recovery is equally important: after the shadow swing, sprint back to center using crossover steps.','The crossover is for distance; the shuffle is for adjustment. Know which to use.']::text[], ARRAY['Shuffling for wide balls — too slow to cover the distance in time.','Crossover without hip turn — produces a stiff, slow movement.','Not recovering after the wide movement — stands at the sideline.']::text[], ARRAY['With actual ball: Player 2 feeds real balls — Player 1 must hit from the wide position.','Timed crossover: how fast can Player 1 crossover from center to the sideline cone and back?','Crossover recovery: Player 1 crossovers wide, shadow swings, then crossovers back — all at full speed.']::text[], ARRAY['footwork','crossover step','wide ball','intermediate','speed','lateral']::text[], 'json', '{"p1":{"x":330,"y":855},"p2":{"x":200,"y":480},"moves":[{"x1":200,"y1":850,"x2":330,"y2":855},{"x1":330,"y1":848,"x2":200,"y2":848}],"shots":[{"x1":200,"y1":490,"x2":335,"y2":840}],"areas":[{"x":330,"y":855,"r":20}]}'::jsonb),
  ('FW-005', 'Spider Run: Full Court Footwork Pattern', 'Footwork', 'Court Coverage', 'footwork', 'intermediate', 12, 1, 'individual', 'Build complete court coverage endurance and movement efficiency through the spider run — the classic tennis footwork conditioning pattern. The spider run visits 5 target positions on the court from center baseline, testing every movement direction: forward, lateral, diagonal forward, and diagonal back. It replicates the distances and movement patterns of real match play and is the gold standard tennis footwork conditioning drill.', 'Build complete court coverage endurance and movement efficiency through the spider run — the classic tennis footwork conditioning pattern. The spider run visits 5 target positions on the court from center baseline, testing every movement direction: forward, lateral, diagonal forward, and diagonal back. It replicates the distances and movement patterns of real match play and is the gold standard tennis footwork conditioning drill.', 'Place cones at 5 positions on the court from Player 1''s baseline perspective: center net strap (T), left net post corner, right net post corner, left baseline corner, right baseline corner. Player 1 starts at center baseline and touches each cone in sequence, returning to center after every cone.', ARRAY['Player 1 starts at center baseline.','Sprint to the center net strap (T position) — touch it — sprint back to center.','Sprint to the left net post corner — touch it — sprint back to center.','Sprint to the right net post corner — touch it — sprint back to center.','Sprint to the left baseline corner — touch it — sprint back to center.','Sprint to the right baseline corner — touch it — sprint back to center.','That is 1 complete spider run. Rest 90 seconds. Repeat 4 times. Track total time.']::text[], ARRAY['Touch each cone with the hand closest to it — this forces a full lean and reach.','Use crossover steps for diagonal sprints — faster than straight running for angular distances.','Sprint back to center as fast as the sprint out — the recovery is part of the drill.','Keep the body low throughout — upright running is slower on short court distances.','Breathe rhythmically — one exhale per 2 steps maintains oxygen flow.']::text[], ARRAY['Jogging instead of sprinting — must simulate match-pace movement.','Not returning to center after each cone — skipping the recovery defeats the drill.','Stopping to touch the cone — must touch on the run, not stop and touch.']::text[], ARRAY['Time-based: compete against personal best time for the 5-cone spider run.','Backward spider: sprint out forward, shuffle/backpedal back to center.','Shadow swing at each cone: simulate a shot at each position — adds tennis-specific specificity.']::text[], ARRAY['footwork','spider run','court coverage','intermediate','conditioning','agility']::text[], 'json', '{"p1":{"x":200,"y":850},"moves":[{"x1":200,"y1":850,"x2":200,"y2":480},{"x1":200,"y1":480,"x2":200,"y2":850},{"x1":200,"y1":850,"x2":65,"y2":480},{"x1":65,"y1":480,"x2":200,"y2":850},{"x1":200,"y1":850,"x2":335,"y2":480},{"x1":335,"y1":480,"x2":200,"y2":850},{"x1":200,"y1":850,"x2":65,"y2":850},{"x1":65,"y1":850,"x2":200,"y2":850},{"x1":200,"y1":850,"x2":335,"y2":850}],"cones":[{"x":200,"y":480},{"x":65,"y":480},{"x":335,"y":480},{"x":65,"y":850},{"x":335,"y":850}]}'::jsonb),
  ('FW-006', 'Recovery to Center: The Habit of Repositioning', 'Footwork', 'Recovery', 'footwork', 'beginner', 12, 2, 'pairs', 'Build the automatic habit of recovering to the center baseline after every shot. Poor recovery positioning is one of the most common tactical and physical errors at all levels — players who stay where they hit leave massive gaps on the other side of the court. This drill makes recovery to center a trained reflex rather than an occasional afterthought.', 'Build the automatic habit of recovering to the center baseline after every shot. Poor recovery positioning is one of the most common tactical and physical errors at all levels — players who stay where they hit leave massive gaps on the other side of the court. This drill makes recovery to center a trained reflex rather than an occasional afterthought.', 'Player 2 feeds balls alternating to Player 1''s forehand and backhand. Player 1 must hit each ball and physically sprint back to the center cone before the next ball is fed. The center cone is non-negotiable — Player 1 must touch it.', ARRAY['Place a cone at the center baseline mark.','Player 2 feeds to Player 1''s forehand — Player 1 hits and immediately sprints to touch the center cone.','Player 2 feeds to Player 1''s backhand — Player 1 hits and immediately sprints to touch the center cone.','Continue alternating. The center cone must be touched after every single shot.','Repeat 20 exchanges. Rest 60 seconds. Play 3 rounds.']::text[], ARRAY['Push off the outside foot the moment you complete the swing — this is the recovery launch.','Don''t watch the ball land — start recovering as the shot leaves the racket.','Sprint to center, don''t shuffle — the cone creates urgency that shuffling cannot.','Anticipate the next ball during the recovery — look for Player 2''s preparation.','The center cone makes the recovery tangible — players cannot cheat by stopping halfway.']::text[], ARRAY['Watching the shot land before recovering — loses a full second of recovery time.','Shuffling to center instead of sprinting — too slow when the next ball comes quickly.','Not reaching center before the next feed — habitually giving up the center.']::text[], ARRAY['No cone: Player 1 must verbally call ''center'' when they reach the recovery position.','Faster feeds: Player 2 decreases time between feeds — Player 1 must recover faster.','Wide and center: feeds go wide, Player 1 must recover all the way to center despite the extra distance.']::text[], ARRAY['footwork','recovery','center baseline','beginner','positioning','habit']::text[], 'json', '{"p1":{"x":200,"y":850},"p2":{"x":200,"y":480},"moves":[{"x1":280,"y1":850,"x2":200,"y2":850},{"x1":200,"y1":850,"x2":120,"y2":850},{"x1":120,"y1":850,"x2":200,"y2":850}],"shots":[{"x1":200,"y1":490,"x2":280,"y2":840},{"x1":200,"y1":490,"x2":120,"y2":840}],"cones":[{"x":200,"y":850}]}'::jsonb),
  ('FW-007', 'Forward Sprint to Short Ball: Closing Distance', 'Footwork', 'Forward Movement', 'footwork', 'intermediate', 10, 2, 'pairs', 'Train the forward sprint to a short ball — the movement pattern used to attack a ball that lands inside the service line. Recognizing the short ball early and sprinting decisively forward is one of the most high-value footwork skills in tennis. Players who close on short balls quickly put the opponent immediately on defense; players who hesitate or jog allow the short ball opportunity to vanish.', 'Train the forward sprint to a short ball — the movement pattern used to attack a ball that lands inside the service line. Recognizing the short ball early and sprinting decisively forward is one of the most high-value footwork skills in tennis. Players who close on short balls quickly put the opponent immediately on defense; players who hesitate or jog allow the short ball opportunity to vanish.', 'Player 1 starts at the baseline. Player 2 feeds short balls — landing inside the service line. Player 1 must sprint forward and hit the short ball before it bounces a second time. The quality of the shot is secondary to the speed of the movement.', ARRAY['Player 1 starts at center baseline.','Player 2 feeds a short ball — landing inside the service line.','Player 1 must call ''short ball!'' and sprint forward immediately.','Player 1 must contact the ball before it bounces a second time.','After the shot, Player 1 either approaches the net or recovers. Repeat 15 times.']::text[], ARRAY['The recognition trigger is the ball clearing the net at a low height — train your eye to see this.','First step must be forward — not sideways, not backward, directly forward.','Sprint in a straight line toward the ball — diagonal routes waste time.','Lean forward during the sprint — body momentum helps create the forward swing.','After the shot, read the situation: come to net if the shot was deep, recover if it was short.']::text[], ARRAY['Jogging to the short ball — by the time a jog arrives, the opportunity is smaller.','First step sideways instead of forward — loses distance in the wrong direction.','Stopping before the contact — momentum should carry through the shot, not stop before it.']::text[], ARRAY['Short ball from different positions: Player 2 feeds short balls to forehand, center, and backhand.','Short ball and volley: after the short ball attack, Player 1 approaches and volleys the next ball.','Race the short ball: Player 2 simultaneously feeds a short ball and starts a stopwatch — Player 1 must arrive within X seconds.']::text[], ARRAY['footwork','forward sprint','short ball','intermediate','attack','recognition']::text[], 'json', '{"p1":{"x":200,"y":660},"p2":{"x":200,"y":480},"moves":[{"x1":200,"y1":850,"x2":200,"y2":660}],"shots":[{"x1":200,"y1":490,"x2":200,"y2":680},{"x1":200,"y1":655,"x2":95,"y2":100}],"areas":[{"x":200,"y":680,"r":25}],"cones":[{"x":200,"y":680}]}'::jsonb),
  ('FW-008', 'Backpedal to Lob: Retreating Without Losing the Ball', 'Footwork', 'Backward Movement', 'footwork', 'intermediate', 10, 2, 'pairs', 'Develop the retreat technique for deep lobs — using crossover steps instead of backpedaling to move backward quickly. Most players backpedal (run backward facing the net) when chasing a lob, which is slow, unstable, and forces a completely blind run. Elite players turn sideways and use crossover steps to retreat faster and with better balance, tracking the ball over their shoulder.', 'Develop the retreat technique for deep lobs — using crossover steps instead of backpedaling to move backward quickly. Most players backpedal (run backward facing the net) when chasing a lob, which is slow, unstable, and forces a completely blind run. Elite players turn sideways and use crossover steps to retreat faster and with better balance, tracking the ball over their shoulder.', 'Player 1 starts at the net. Player 2 throws or hits deep lobs over Player 1''s head. Player 1 must turn sideways and retreat using crossover steps to reach the ball before it bounces twice.', ARRAY['Player 1 starts at the net.','Player 2 throws a deep lob over Player 1''s head.','Player 1 immediately turns sideways (90 degrees) and retreats using crossover steps.','Player 1 tracks the ball over the shoulder and either smashes or plays a groundstroke.','Repeat 15 times alternating deep lobs to left and right. Rest 60 seconds between sets.']::text[], ARRAY['Turn sideways immediately — facing the net while retreating is slow and unstable.','Use crossover steps to retreat: the foot furthest from the target crosses behind.','Keep your eyes on the ball by looking over the leading shoulder.','Point the non-dominant arm at the ball while retreating — maintains visual tracking.','Never take your eye off the ball during the retreat — losing sight of the ball ends the point.']::text[], ARRAY['Backpedaling facing the net — slow, unstable, and completely wrong for deep retreats.','Losing sight of the ball during the turn — causes complete misjudgment of depth.','Retreating in a straight line instead of diagonally toward the ball trajectory.']::text[], ARRAY['Timed retreat: how fast can Player 1 retreat from the net to the baseline using crossover steps?','Retreat and smash: lob is shallow enough to smash — Player 1 must recognize and smash.','Retreat and lob back: Player 1 retrieves deep lob and lobs back — sustains the drill.']::text[], ARRAY['footwork','backpedal','retreat','lob','intermediate','crossover']::text[], 'json', '{"p1":{"x":200,"y":750},"p2":{"x":200,"y":60},"moves":[{"x1":200,"y1":520,"x2":200,"y2":750}],"shots":[{"x1":200,"y1":70,"x2":200,"y2":600},{"x1":200,"y1":745,"x2":200,"y2":100}],"areas":[{"x":200,"y":750,"r":25}]}'::jsonb),
  ('FW-009', 'Figure-Eight Footwork: Continuous Direction Changes', 'Footwork', 'Agility', 'footwork', 'intermediate', 10, 1, 'individual', 'Build agility and continuous direction-change ability through the figure-eight footwork pattern. Tennis demands constant changes of direction — rarely do players move in a straight line for more than 3 steps. The figure-eight drill trains the body to decelerate, plant, and re-accelerate in a new direction rapidly and efficiently — the exact motor pattern needed for chasing wide balls and recovering to center.', 'Build agility and continuous direction-change ability through the figure-eight footwork pattern. Tennis demands constant changes of direction — rarely do players move in a straight line for more than 3 steps. The figure-eight drill trains the body to decelerate, plant, and re-accelerate in a new direction rapidly and efficiently — the exact motor pattern needed for chasing wide balls and recovering to center.', 'Place two cones 8 feet apart on the baseline. Player 1 runs a figure-eight pattern around the cones continuously — going around the right cone, then around the left cone, forming a continuous figure-eight pattern.', ARRAY['Place two cones 8 feet apart centered on the baseline.','Player 1 starts between the cones and begins the figure-eight: run around the right cone, then around the left cone.','Continue the figure-eight continuously for 20 seconds.','Rest 30 seconds. Repeat 6 rounds.','Focus on tight, controlled turns around each cone — not wide, sloppy arcs.']::text[], ARRAY['Plant the outside foot firmly to redirect — the plant stops momentum and launches in the new direction.','Stay low throughout the figure-eight — standing up on the turns kills momentum.','Drive the arms during the turns — arms generate angular momentum in tight turns.','Look through the pattern, not at your feet — eyes up at all times.','Tight turns are better than fast turns — precision before speed.']::text[], ARRAY['Wide, lazy turns around the cones — covers too much extra ground.','Slowing down to make the turns — should be able to turn at near-full speed.','Looking down at the feet — takes eyes off the court during real play.']::text[], ARRAY['Wider cones: increase to 12 feet apart — more ground to cover between turns.','Shadow swings at each cone: simulate a groundstroke at each cone during the figure-eight.','Timed figure-eight: how many complete figure-eights in 20 seconds? Compete against personal best.']::text[], ARRAY['footwork','figure eight','agility','intermediate','direction change','movement']::text[], 'json', '{"p1":{"x":200,"y":850},"moves":[{"x1":200,"y1":850,"x2":265,"y2":810},{"x1":265,"y1":810,"x2":280,"y2":850},{"x1":280,"y1":850,"x2":265,"y2":890},{"x1":265,"y1":890,"x2":200,"y2":850},{"x1":200,"y1":850,"x2":135,"y2":810},{"x1":135,"y1":810,"x2":120,"y2":850},{"x1":120,"y1":850,"x2":135,"y2":890},{"x1":135,"y1":890,"x2":200,"y2":850}],"cones":[{"x":280,"y":850},{"x":120,"y":850}]}'::jsonb),
  ('FW-010', 'Three-Ball Lateral Pattern: Wide, Center, Wide', 'Footwork', 'Lateral Movement', 'footwork', 'intermediate', 12, 2, 'pairs', 'Train the most common lateral footwork pattern in tennis — wide forehand, recovery to center, wide backhand. This three-ball sequence replicates the exact movement demand of a baseline rally where the opponent alternates wide balls. It tests the speed of movement, the quality of the recovery, and the ability to maintain stroke quality under continuous lateral pressure.', 'Train the most common lateral footwork pattern in tennis — wide forehand, recovery to center, wide backhand. This three-ball sequence replicates the exact movement demand of a baseline rally where the opponent alternates wide balls. It tests the speed of movement, the quality of the recovery, and the ability to maintain stroke quality under continuous lateral pressure.', 'Player 2 feeds three balls in sequence: wide to Player 1''s forehand, center, wide to Player 1''s backhand. Player 1 must hit all three balls and recover to center between each one. Player 2 feeds the next ball as soon as Player 1 recovers.', ARRAY['Player 2 feeds wide to Player 1''s forehand — Player 1 hits and recovers to center.','Player 2 immediately feeds center — Player 1 hits and recovers to center.','Player 2 immediately feeds wide to Player 1''s backhand — Player 1 hits and recovers to center.','Rest 30 seconds. Repeat 10 three-ball sequences per set. Play 3 sets.','Increase pace and width of feeds each set.']::text[], ARRAY['Recovery after the wide forehand is the most critical — it sets up the center ball.','Don''t watch the wide shot land — start recovering immediately after contact.','The center ball is often the hardest — Player 1 is mid-recovery and the ball arrives quickly.','After the wide backhand, the recovery covers the most ground — use crossover steps.','Breathe between all three shots — three rapid shots in sequence creates oxygen debt quickly.']::text[], ARRAY['Incomplete recovery after the first ball — center ball arrives before the player is ready.','Slow crossover steps on the wide backhand — the backhand side often has slower footwork.','No recovery after the third ball — sequence ends but body stays wide.']::text[], ARRAY['Four-ball sequence: wide FH, center, wide BH, center — adds a fourth ball.','Reverse sequence: wide BH, center, wide FH — same movement demands, opposite order.','No recovery rule: Player 2 feeds the next ball immediately without waiting for recovery — maximum pressure.']::text[], ARRAY['footwork','lateral','three ball','intermediate','pattern','recovery']::text[], 'json', '{"p1":{"x":200,"y":850},"p2":{"x":200,"y":480},"moves":[{"x1":200,"y1":850,"x2":330,"y2":850},{"x1":330,"y1":850,"x2":200,"y2":850},{"x1":200,"y1":850,"x2":70,"y2":850}],"shots":[{"x1":200,"y1":490,"x2":330,"y2":840},{"x1":200,"y1":490,"x2":200,"y2":840},{"x1":200,"y1":490,"x2":70,"y2":840}]}'::jsonb),
  ('FW-011', 'Shadow Footwork: No Ball Movement Training', 'Footwork', 'Movement Pattern', 'footwork', 'beginner', 10, 2, 'pairs', 'Build complete movement patterns through shadow footwork — performing all the footwork of a real rally without any ball. Shadow footwork allows players to train movement at full intensity without the cognitive distraction of hitting a ball. It is the fastest way to ingrain new footwork habits because every repetition is pure movement, and the player can focus entirely on technique.', 'Build complete movement patterns through shadow footwork — performing all the footwork of a real rally without any ball. Shadow footwork allows players to train movement at full intensity without the cognitive distraction of hitting a ball. It is the fastest way to ingrain new footwork habits because every repetition is pure movement, and the player can focus entirely on technique.', 'Player 2 acts as the ''director'' — calling directions, pointing, or feeding phantom balls. Player 1 performs all footwork movements in response: split step, first step, movement, shadow swing, recovery. No ball is used.', ARRAY['Player 2 stands across the net and calls directions rapidly: ''forehand!'', ''backhand!'', ''short!'', ''wide forehand!'', ''wide backhand!''.','Player 1 must perform the complete footwork for each called shot: split step, first step, move to position, shadow swing, recover.','Player 2 calls the next direction as soon as Player 1 returns to center.','Continue for 30 seconds on, 30 seconds rest. Repeat 6 rounds.','Focus entirely on the speed and quality of the footwork — not on the swing.']::text[], ARRAY['Split step on every call — even if you are already in position, split step before moving.','Exaggerate the first step — bigger, more explosive than you think is necessary.','Complete the shadow swing at every position — don''t cut the motion short.','Recover to center after every shadow swing — even in the shadow drill, recovery matters.','Eyes up and forward — watch Player 2''s signals, not the ground.']::text[], ARRAY['Skipping the split step — defeats the purpose of shadow footwork training.','Not recovering to center — builds bad habits in the shadow drill that transfer to real play.','Half-swings on the shadow — should be full swings to train the complete movement cycle.']::text[], ARRAY['Self-directed shadow: Player 1 calls their own shots aloud and moves accordingly.','Timed rounds: how many complete shadow movement cycles in 30 seconds?','Random direction: Player 2 points instead of calling — adds visual reaction to the drill.']::text[], ARRAY['footwork','shadow','movement pattern','beginner','no ball','habit']::text[], 'json', '{"p1":{"x":200,"y":850},"p2":{"x":200,"y":480},"moves":[{"x1":200,"y1":850,"x2":310,"y2":850},{"x1":310,"y1":850,"x2":200,"y2":850},{"x1":200,"y1":850,"x2":90,"y2":850},{"x1":90,"y1":850,"x2":200,"y2":850},{"x1":200,"y1":850,"x2":200,"y2":720}],"areas":[{"x":200,"y":850,"r":20}]}'::jsonb),
  ('FW-012', 'Diagonal Forward Sprint: The Attack Move', 'Footwork', 'Forward Movement', 'footwork', 'intermediate', 10, 2, 'pairs', 'Train the diagonal forward sprint — used to attack short balls that land wide and forward simultaneously. Unlike the purely lateral shuffle or the purely forward sprint, most short ball opportunities require a diagonal approach: forward and to the side at the same time. This drill isolates and trains that specific movement so it becomes natural and fast under match conditions.', 'Train the diagonal forward sprint — used to attack short balls that land wide and forward simultaneously. Unlike the purely lateral shuffle or the purely forward sprint, most short ball opportunities require a diagonal approach: forward and to the side at the same time. This drill isolates and trains that specific movement so it becomes natural and fast under match conditions.', 'Player 2 feeds short balls at diagonal angles — short and wide to the forehand, and short and wide to the backhand. Player 1 must sprint diagonally to each ball. Cones mark the target positions.', ARRAY['Place cones at the two diagonal short ball positions: short-wide forehand and short-wide backhand.','Player 2 feeds a short-wide ball to Player 1''s forehand — Player 1 sprints diagonally forward-right.','Player 1 hits the ball and recovers diagonally backward to center.','Player 2 feeds short-wide to the backhand — Player 1 sprints diagonally forward-left.','Alternate sides for 12 sequences. Rest 60 seconds. Play 3 sets.']::text[], ARRAY['The diagonal sprint starts with a forward-angled first step — not a sideways step.','Keep the body low during the diagonal sprint — standing up slows the approach.','Lean into the diagonal direction — body angle drives the sprint.','Recovery is also diagonal: back and toward center simultaneously.','The diagonal sprint is faster than going sideways then forward separately — commit to the angle.']::text[], ARRAY['Going sideways then forward separately — creates an L-shaped path instead of a diagonal.','Upright sprint — standing tall reduces sprint speed and compromises the swing on arrival.','Not committing to the diagonal angle — hesitating causes a late arrival.']::text[], ARRAY['Add a volley after the diagonal sprint: Player 1 hits the short ball and follows to the net.','Diagonal sprint competition: how fast can Player 1 reach each cone from center?','Both diagonals: Player 2 randomly feeds either short-wide FH or short-wide BH — Player 1 must read.']::text[], ARRAY['footwork','diagonal sprint','forward','intermediate','attack','short ball']::text[], 'json', '{"p1":{"x":290,"y":680},"p2":{"x":200,"y":480},"moves":[{"x1":200,"y1":850,"x2":290,"y2":680},{"x1":290,"y1":670,"x2":200,"y2":850}],"shots":[{"x1":200,"y1":490,"x2":295,"y2":695},{"x1":285,"y1":675,"x2":95,"y2":100}],"cones":[{"x":290,"y":680},{"x":110,"y":680}]}'::jsonb),
  ('FW-013', 'Open Stance vs Closed Stance Footwork Decision', 'Footwork', 'Stance', 'footwork', 'intermediate', 12, 2, 'pairs', 'Train the decision between open stance and closed stance footwork — knowing when each is appropriate and executing the footwork for each automatically. Open stance is used when there is not enough time to set up properly or when the ball is wide. Closed stance is used when there is time and the ball allows a step-in. Most players default to one stance regardless — this drill builds both and trains the decision.', 'Train the decision between open stance and closed stance footwork — knowing when each is appropriate and executing the footwork for each automatically. Open stance is used when there is not enough time to set up properly or when the ball is wide. Closed stance is used when there is time and the ball allows a step-in. Most players default to one stance regardless — this drill builds both and trains the decision.', 'Player 2 feeds balls varying in pace and width. Fast and wide balls demand open stance; slow and central balls invite closed stance. Player 1 must identify the appropriate stance and use the corresponding footwork.', ARRAY['Player 2 feeds slow, central balls — Player 1 steps into a closed stance and hits.','Player 2 feeds fast, wide balls — Player 1 uses open stance and rotates from a planted foot.','After 5 each, Player 2 mixes without signaling — Player 1 must read and choose.','Play 20 random balls. Track: correct stance choice vs incorrect.','Focus on the quality of the footwork for each stance, not just getting the ball in.']::text[], ARRAY['Closed stance: step toward the ball with the front foot — weight transfers through the swing.','Open stance: plant the outside foot and rotate the hips and torso instead of stepping.','Decision trigger: if you have time to step in, use closed. If you are rushed or wide, use open.','The closed stance generates more power; the open stance is faster to set up and recover from.','Never mix the two: don''t take a half-step in from an open stance — commit to one.']::text[], ARRAY['Using open stance on balls that allow closed stance — gives up available power.','Attempting closed stance on wide, fast balls — not enough time, produces a cramped swing.','Half-committing to either stance — the worst of both worlds.']::text[], ARRAY['Stance-specific practice: 10 minutes open stance only, then 10 minutes closed stance only.','Partner call: Player 2 calls ''open'' or ''closed'' before each feed — Player 1 executes on command.','Slow motion: practice the footwork for each stance in slow motion — build the proprioceptive feel.']::text[], ARRAY['footwork','stance','open stance','closed stance','intermediate','decision']::text[], 'json', '{"p1":{"x":200,"y":850},"p2":{"x":200,"y":480},"shots":[{"x1":200,"y1":490,"x2":200,"y2":840},{"x1":200,"y1":490,"x2":310,"y2":840}],"moves":[{"x1":200,"y1":850,"x2":220,"y2":840},{"x1":200,"y1":850,"x2":310,"y2":852}],"areas":[{"x":220,"y":840,"r":20},{"x":310,"y":852,"r":20}]}'::jsonb),
  ('FW-014', 'Cone Ladder: Rapid Foot Speed Training', 'Footwork', 'Foot Speed', 'footwork', 'beginner', 10, 1, 'individual', 'Build rapid foot speed and coordination through a cone ladder sequence. Fast feet in tennis are not just about raw speed — they require precise, coordinated footwork that can be repeated hundreds of times per match without breaking down. The cone ladder builds the neuromuscular coordination that makes fast feet sustainable over long matches.', 'Build rapid foot speed and coordination through a cone ladder sequence. Fast feet in tennis are not just about raw speed — they require precise, coordinated footwork that can be repeated hundreds of times per match without breaking down. The cone ladder builds the neuromuscular coordination that makes fast feet sustainable over long matches.', 'Place 6 cones in a straight line 2 feet apart. Player 1 performs various footwork patterns through the cone ladder: two feet in each space, one foot in each space, lateral steps through the ladder, and icky shuffle pattern.', ARRAY['Pattern 1: two feet in each cone space — both feet enter and exit each space before moving to the next.','Pattern 2: one foot in each cone space — alternate feet, one per space.','Pattern 3: lateral run through the ladder — both feet enter each space moving sideways.','Pattern 4: icky shuffle — in, out, in, out through the ladder.','Repeat each pattern 3 times. Rest 20 seconds between patterns.']::text[], ARRAY['Focus on foot placement accuracy first — speed comes after consistency.','Arms pump with every step — the arms drive the legs.','Eyes forward, not down at the cones — looking down slows the pattern.','Land on the balls of the feet — heel striking is slow.','Keep the movements small and precise — high-stepping wastes energy.']::text[], ARRAY['Looking at the feet — takes eyes off the court in real play.','Heel striking — significantly slows foot speed.','Large, high steps — wastes energy and vertical movement.']::text[], ARRAY['Tennis-specific: hold a racket throughout the ladder — adds the weight and grip challenge.','Timed ladder: how fast can Player 1 complete each pattern? Track personal bests.','Ladder then sprint: after completing the ladder, sprint immediately to a cone 10 feet away.']::text[], ARRAY['footwork','cone ladder','foot speed','beginner','coordination','agility']::text[], 'json', '{"p1":{"x":200,"y":850},"moves":[{"x1":200,"y1":850,"x2":200,"y2":740}],"cones":[{"x":200,"y":850},{"x":200,"y":830},{"x":200,"y":810},{"x":200,"y":790},{"x":200,"y":770},{"x":200,"y":750}]}'::jsonb),
  ('FW-015', 'Approach Footwork: Stop, Plant, and Drive', 'Footwork', 'Forward Movement', 'footwork', 'intermediate', 12, 2, 'pairs', 'Train the approach footwork sequence — the specific movement pattern used when approaching the net on a short ball. The approach requires three distinct footwork phases: sprint to the ball, stop with a planted foot, swing and drive forward into the net. Many players fail to plant before the approach shot, causing off-balance, weak approach shots. This drill isolates the plant-and-drive mechanism.', 'Train the approach footwork sequence — the specific movement pattern used when approaching the net on a short ball. The approach requires three distinct footwork phases: sprint to the ball, stop with a planted foot, swing and drive forward into the net. Many players fail to plant before the approach shot, causing off-balance, weak approach shots. This drill isolates the plant-and-drive mechanism.', 'Player 2 feeds short balls inside the service line. Player 1 sprints forward, plants their foot before contact, hits the approach shot, and continues sprinting to the net. The plant step is mandatory — Player 1 must pause for one beat before hitting.', ARRAY['Player 2 feeds a short ball inside Player 1''s service line.','Player 1 sprints forward from the baseline.','Player 1 plants their dominant foot one step behind the ball position — stops the sprint for one beat.','Player 1 hits the approach shot from the planted position.','Player 1 continues sprinting to the net after contact. Repeat 15 times.']::text[], ARRAY['The plant foot lands one step behind the ideal contact point — creates space to swing.','Plant firmly — a soft plant shifts during the swing and changes the contact point.','After the plant, swing through the ball and simultaneously push off the plant foot toward the net.','The plant-and-drive creates approach shot power — passive approaches are weak because there is no drive.','The plant is a landing, not a stop — it decelerates, not halts, the forward movement.']::text[], ARRAY['No plant — hitting while still running at full speed creates terrible contact.','Too long a plant — stops the forward momentum completely, loses the drive.','Plant too close to the ball — jams the swing.']::text[], ARRAY['Plant to different sides: approach off forehand, plant, hit — approach off backhand, plant, hit.','Plant and volley: after the approach, Player 2 feeds a volley ball immediately.','Running approach: plant on the fly — gradually reduce the plant pause until it''s seamless.']::text[], ARRAY['footwork','approach','plant step','intermediate','net play','drive']::text[], 'json', '{"p1":{"x":200,"y":680},"p2":{"x":200,"y":480},"moves":[{"x1":200,"y1":850,"x2":200,"y2":700},{"x1":200,"y1":700,"x2":200,"y2":540}],"shots":[{"x1":200,"y1":490,"x2":200,"y2":710},{"x1":200,"y1":695,"x2":95,"y2":100}],"areas":[{"x":200,"y":700,"r":20}]}'::jsonb)
